import{_ as t,o as r,c as n,Q as e}from"./chunks/framework.48927342.js";const f=JSON.parse('{"title":"Module 4: Shopping and Food","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/modules/maltese-module4-analysis.md","filePath":"en/more/maltese/modules/maltese-module4-analysis.md"}'),o={name:"en/more/maltese/modules/maltese-module4-analysis.md"},s=e('<h1 id="module-4-shopping-and-food" tabindex="-1">Module 4: Shopping and Food <a class="header-anchor" href="#module-4-shopping-and-food" aria-label="Permalink to &quot;Module 4: Shopping and Food&quot;">​</a></h1><p><strong>Ix-xiri u l-ikel — Shopping and Food</strong></p><h2 id="overall-outline" tabindex="-1">Overall Outline <a class="header-anchor" href="#overall-outline" aria-label="Permalink to &quot;Overall Outline&quot;">​</a></h2><table><thead><tr><th>PDF page</th><th>Textbook footer</th><th>Content</th></tr></thead><tbody><tr><td>1</td><td>none</td><td>Cover: Shopping and Food</td></tr><tr><td>2</td><td>1</td><td>Grocery dialogue: buying ham, cheese, paying and change</td></tr><tr><td>3</td><td>2</td><td>Fruit, vegetable, meat and fish vocabulary</td></tr><tr><td>4</td><td>3</td><td>Clothing list; what to wear when going out, what to buy for cooking</td></tr><tr><td>5</td><td>4</td><td>Fruit and vegetable English–Maltese vocabulary table</td></tr><tr><td>6</td><td>5</td><td>Oreo cake ingredients, weights and capacities</td></tr><tr><td>7</td><td>6</td><td>Method steps, ordinal numbers, writing quantities in words</td></tr><tr><td>8</td><td>7</td><td>Imperatives and sentences 1–21</td></tr><tr><td>9</td><td>8</td><td>Imperatives and sentences 22–30; describing the woman&#39;s outfit</td></tr><tr><td>10</td><td>9</td><td>Describing the man&#39;s outfit; matching eight people with texts</td></tr><tr><td>11</td><td>10</td><td>Numbers 1–20, number listening, phone numbers</td></tr><tr><td>12</td><td>11</td><td>Phone numbers (continued), sums</td></tr><tr><td>13</td><td>12</td><td>20–100, compound numbers, 101 and 105</td></tr><tr><td>14</td><td>13</td><td>Confusing-number listening; spelling numbers in sentences</td></tr><tr><td>15</td><td>14</td><td>Number forms and singular/plural before nouns</td></tr><tr><td>16</td><td>15</td><td>Number–noun agreement fill-in</td></tr><tr><td>17</td><td>16</td><td>Standalone numbers vs numbers before nouns</td></tr><tr><td>18</td><td>17</td><td>The dual: two days, two hands, two years, etc.</td></tr><tr><td>19</td><td>18</td><td>Quantity adverbs and fill-in in context</td></tr></tbody></table><h2 id="cover-page-breakdown" tabindex="-1">Cover Page Breakdown <a class="header-anchor" href="#cover-page-breakdown" aria-label="Permalink to &quot;Cover Page Breakdown&quot;">​</a></h2><table><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>MQF 2 – Maltese Language and Cultural Orientation for Foreigners</td><td>MQF Level 2: Maltese language and cultural orientation course for foreigners.<br><strong>MQF</strong> Malta Qualifications Framework<br><strong>2</strong> Level 2; not &quot;second module&quot;<br><strong>Maltese Language</strong> Maltese language<br><strong>and</strong> and<br><strong>Cultural Orientation</strong> cultural orientation / cultural introduction<br><strong>for Foreigners</strong> for foreigners.</td></tr><tr><td>Module 4 – Ix-xiri u l-ikel</td><td>Module 4: shopping and food.<br><strong>Module 4</strong> Module 4<br><strong>ix-xiri</strong> the shopping (assimilated definite article)<br><strong>u</strong> and<br><strong>l-ikel</strong> the food.</td></tr><tr><td>Shopping and Food</td><td>Shopping and food.<br><strong>shopping</strong> shopping<br><strong>and</strong> and<br><strong>food</strong> food.</td></tr><tr><td>Is-Sur E. Sammut addattat min-noti tas-Sa A. Cefai</td><td>Mr E. Sammut adapted from the notes of Ms A. Cefai.<br><strong>is-Sur</strong> Mr<br><strong>E. Sammut</strong> a name<br><strong>addattat</strong> adapted<br><strong>min-noti</strong> from the notes<br><strong>tas-Sa</strong> of Ms (abbreviated title, kept as in the textbook)<br><strong>A. Cefai</strong> a name.</td></tr><tr><td>Learning Works</td><td>Institution/brand name, kept as a proper name.<br><strong>Learning</strong> learning<br><strong>Works</strong> part of the brand name; not translated as an ordinary phrase.</td></tr></tbody></table><p>The repeated signature on later pages has the same meaning and is not explained page by page.</p><hr><h2 id="_1-shopping-dialogue-line-by-line" tabindex="-1">1 Shopping Dialogue, Line by Line <a class="header-anchor" href="#_1-shopping-dialogue-line-by-line" aria-label="Permalink to &quot;1 Shopping Dialogue, Line by Line&quot;">​</a></h2><table><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Il-Qari – Aqra dan id-djalogu.</td><td>Reading: read this dialogue.<br><strong>il-qari</strong> the reading<br><strong>aqra</strong> read (imperative)<br><strong>dan</strong> this<br><strong>id-djalogu</strong> the dialogue.</td></tr><tr><td>Klara marret tixtri mingħand tal-merċa.</td><td>Klara went shopping at the grocer&#39;s.<br><strong>Klara</strong> a name<br><strong>marret</strong> she went<br><strong>tixtri</strong> she buys<br><strong>mingħand</strong> from (someone/shop)<br><strong>tal-merċa</strong> the grocer, grocery seller.</td></tr><tr><td>Bonġu Tumas, agħtini kwart perżut jekk jogħġbok.</td><td>Good morning, Tumas, give me a quarter-weight of ham, please.<br><strong>bonġu</strong> good morning<br><strong>Tumas</strong> a name<br><strong>agħtini</strong> give me (agħti + -ni)<br><strong>kwart</strong> a quarter; for loose goods usually about 250 g<br><strong>perżut</strong> ham<br><strong>jekk jogħġbok</strong> please (fixed polite phrase).</td></tr><tr><td>Bonġu Klar, ara ġej.</td><td>Good morning, Klara, coming right up.<br><strong>bonġu</strong> good morning<br><strong>Klar</strong> an affectionate short form of Klara<br><strong>ara</strong> look (conversational prompt)<br><strong>ġej</strong> coming; here, &quot;right away&quot;.</td></tr><tr><td>Għandi bżonn ukoll nofs kwart ġobon tal-qoxra ħamra u ħames mitt gramma ġobon maħkuk.</td><td>I also need half a quarter of red-rind cheese and 500 grams of grated cheese.<br><strong>għandi bżonn</strong> I need<br><strong>ukoll</strong> also<br><strong>nofs kwart</strong> an eighth; about 125 g in the kilogram context<br><strong>ġobon</strong> cheese<br><strong>tal-qoxra</strong> with a rind / of the rind<br><strong>ħamra</strong> red (feminine, modifying qoxra)<br><strong>u</strong> and<br><strong>ħames mitt</strong> five hundred<br><strong>gramma</strong> gram<br><strong>ġobon maħkuk</strong> grated cheese<br><strong>maħkuk</strong> grated.</td></tr><tr><td>Kollox sew... xi ħaġa oħra?</td><td>All right... anything else?<br><strong>kollox</strong> everything<br><strong>sew</strong> well, fine<br><strong>xi ħaġa</strong> something<br><strong>oħra</strong> else (feminine, with ħaġa).</td></tr><tr><td>Le dak kollox, x’għandi nagħtik?</td><td>No, that&#39;s everything; how much should I pay you?<br><strong>le</strong> no<br><strong>dak</strong> that<br><strong>kollox</strong> all<br><strong>x’</strong> what<br><strong>għandi</strong> should I / do I have<br><strong>nagħtik</strong> I give you (payment in the shopping context).</td></tr><tr><td>Tliet ewro u ħamsin ċenteżmu jekk jogħġbok.</td><td>Three euros and fifty cents, please.<br><strong>tliet</strong> three (before a noun)<br><strong>ewro</strong> euros<br><strong>u</strong> and<br><strong>ħamsin</strong> fifty<br><strong>ċenteżmu</strong> cents<br><strong>jekk jogħġbok</strong> please.</td></tr><tr><td>Ħa, hawn għandek erba’ ewro.</td><td>Here, here&#39;s four euros.<br><strong>ħa</strong> here, take it (when handing something)<br><strong>hawn</strong> here<br><strong>għandek</strong> you have, here&#39;s yours<br><strong>erba’</strong> four (before a noun)<br><strong>ewro</strong> euros.</td></tr><tr><td>Mela ħamsin ċenteżmu bqija, saħħa!</td><td>Then fifty cents change, cheers!<br><strong>mela</strong> then, so<br><strong>ħamsin ċenteżmu</strong> fifty cents<br><strong>bqija</strong> the rest, change<br><strong>saħħa</strong> cheers, goodbye; literally &quot;health&quot;.</td></tr><tr><td>Grazzi u l-ġurnata t-tajba.</td><td>Thanks, and have a good day.<br><strong>grazzi</strong> thanks<br><strong>u</strong> and<br><strong>l-ġurnata</strong> the day<br><strong>t-tajba</strong> good (feminine); the whole phrase is a wish.</td></tr></tbody></table><h3 id="comprehension-questions-and-reference-answers" tabindex="-1">Comprehension Questions and Reference Answers <a class="header-anchor" href="#comprehension-questions-and-reference-answers" aria-label="Permalink to &quot;Comprehension Questions and Reference Answers&quot;">​</a></h3><table><thead><tr><th>Question and answer</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Xi xtrat Klara? — Klara xtrat kwart perżut, nofs kwart ġobon tal-qoxra ħamra u ħames mitt gramma ġobon maħkuk.</td><td>What did Klara buy? — Ham, red-rind cheese and grated cheese, with the quantities matching the dialogue.<br><strong>xi</strong> what<br><strong>xtrat</strong> she bought<br><strong>Klara</strong> a name<br><strong>kwart / nofs kwart</strong> a quarter / an eighth<br><strong>perżut</strong> ham<br><strong>ġobon tal-qoxra ħamra</strong> red-rind cheese<br><strong>ħames mitt gramma</strong> 500 grams<br><strong>ġobon maħkuk</strong> grated cheese.</td></tr><tr><td>Kemm nefqet? — Nefqet tliet ewro u ħamsin ċenteżmu.</td><td>How much did she spend? — €3.50.<br><strong>kemm</strong> how much<br><strong>nefqet</strong> she spent<br><strong>tliet ewro</strong> three euros<br><strong>u</strong> plus<br><strong>ħamsin ċenteżmu</strong> fifty cents.</td></tr><tr><td>F’din il-kaxxa ikteb kemm tista’ oġġetti li tista’ tixtri mingħand tal-merċa.</td><td>In the box, write as many items as you can that you can buy at the grocer&#39;s.<br><strong>f’din il-kaxxa</strong> in this box<br><strong>ikteb</strong> write<br><strong>kemm tista’</strong> as many as you can<br><strong>oġġetti</strong> items<br><strong>li</strong> that<br><strong>tista’ tixtri</strong> you can buy<br><strong>mingħand tal-merċa</strong> from the grocer.</td></tr></tbody></table><p>Reference list for exercise 3 (one word per line):</p><ul><li><strong>ħobż</strong> bread.</li><li><strong>ħalib</strong> milk.</li><li><strong>ġobon</strong> cheese.</li><li><strong>perżut</strong> ham.</li><li><strong>bajd</strong> eggs (collective noun).</li><li><strong>butir</strong> butter.</li><li><strong>dqiq</strong> flour.</li><li><strong>zokkor</strong> sugar.</li><li><strong>melħ</strong> salt.</li><li><strong>żejt</strong> oil.</li><li><strong>ross</strong> rice.</li><li><strong>għaġin</strong> pasta.</li><li><strong>kafè</strong> coffee.</li><li><strong>te</strong> tea.</li><li><strong>gallettini</strong> biscuits.</li></ul><hr><h2 id="_2-exercise-4-fruit-and-vegetable-list" tabindex="-1">2 Exercise 4: Fruit and Vegetable List <a class="header-anchor" href="#_2-exercise-4-fruit-and-vegetable-list" aria-label="Permalink to &quot;2 Exercise 4: Fruit and Vegetable List&quot;">​</a></h2><p><strong>F’din il-kaxxa ikteb kemm tista’ frott u ħaxix li ssib mingħand tal-ħaxix.</strong></p><p>In the box, write as many fruits and vegetables as you can find at the greengrocer&#39;s.</p><ul><li><strong>f’din il-kaxxa</strong> in this box.</li><li><strong>ikteb</strong> write.</li><li><strong>kemm tista’</strong> as many as you can.</li><li><strong>frott</strong> fruit (collective).</li><li><strong>u</strong> and.</li><li><strong>ħaxix</strong> vegetables (collective).</li><li><strong>li ssib</strong> that you find.</li><li><strong>mingħand tal-ħaxix</strong> from the greengrocer.</li></ul><p>Reference answers:</p><ul><li><strong>tuffieħ</strong> apples.</li><li><strong>larinġ</strong> oranges.</li><li><strong>banana</strong> bananas.</li><li><strong>lanġas</strong> pears.</li><li><strong>għeneb</strong> grapes.</li><li><strong>lumi</strong> lemons.</li><li><strong>frawli</strong> strawberries.</li><li><strong>patata</strong> potatoes.</li><li><strong>basal</strong> onions.</li><li><strong>tewm</strong> garlic.</li><li><strong>tadam</strong> tomatoes.</li><li><strong>karrotti</strong> carrots.</li><li><strong>ħass</strong> lettuce.</li><li><strong>ħjar</strong> cucumbers.</li></ul><h3 id="exercise-5-the-butcher-s-and-the-fishmonger-s" tabindex="-1">Exercise 5: The Butcher&#39;s and the Fishmonger&#39;s <a class="header-anchor" href="#exercise-5-the-butcher-s-and-the-fishmonger-s" aria-label="Permalink to &quot;Exercise 5: The Butcher&#39;s and the Fishmonger&#39;s&quot;">​</a></h3><p><strong>F’din il-kaxxa ikteb kemm tista’ tipi ta’ laħam li ssib mingħand tal-laħam, u tipi ta’ ħut li ssib mingħand tal-ħut.</strong></p><p>In the box, list the kinds of meat you can find at the butcher&#39;s, and the kinds of fish you can find at the fishmonger&#39;s.</p><ul><li><strong>tipi</strong> kinds.</li><li><strong>ta’ laħam</strong> of meat.</li><li><strong>li ssib</strong> that you find.</li><li><strong>mingħand tal-laħam</strong> from the butcher&#39;s.</li><li><strong>u</strong> and.</li><li><strong>ta’ ħut</strong> of fish.</li><li><strong>mingħand tal-ħut</strong> from the fishmonger&#39;s.</li></ul><table><thead><tr><th>Meat: reference answers</th><th>Fish: reference answers</th></tr></thead><tbody><tr><td><strong>tiġieġ</strong> chicken<br><strong>ċanga</strong> beef<br><strong>majjal</strong> pork<br><strong>ħaruf</strong> lamb<br><strong>fenek</strong> rabbit<br><strong>dundjan</strong> turkey</td><td><strong>tonn</strong> tuna<br><strong>salamun</strong> salmon<br><strong>sardin</strong> sardines<br><strong>lampuki</strong> dolphinfish / the local lampuka fish (plural)<br><strong>awrat</strong> gilthead bream<br><strong>spnott</strong> sea bass</td></tr></tbody></table><p><strong>Note:</strong> <code>tal-laħam / tal-ħut / tal-ħaxix</code> in everyday use can mean the person or shop that sells these goods, not just literally &quot;of meat / of fish / of vegetables&quot;.</p><hr><h2 id="_3-exercise-6-clothing-list" tabindex="-1">3 Exercise 6: Clothing List <a class="header-anchor" href="#_3-exercise-6-clothing-list" aria-label="Permalink to &quot;3 Exercise 6: Clothing List&quot;">​</a></h2><p><strong>F’din il-kaxxa ikteb kemm tista’ oġġetti tal-ħwejjeġ li tista’ tixtri minn ħanut tal-ħwejjeġ.</strong></p><p>In the box, write as many clothing items as you can that you can buy at a clothes shop.</p><ul><li><strong>f’din il-kaxxa</strong> in this box.</li><li><strong>ikteb</strong> write.</li><li><strong>kemm tista’</strong> as many as you can.</li><li><strong>oġġetti tal-ħwejjeġ</strong> clothing items.</li><li><strong>li tista’ tixtri</strong> that you can buy.</li><li><strong>minn</strong> from.</li><li><strong>ħanut tal-ħwejjeġ</strong> clothes shop.</li></ul><p>Reference answers:</p><ul><li><strong>qmis</strong> shirt.</li><li><strong>libsa</strong> dress / suit.</li><li><strong>dublett</strong> skirt.</li><li><strong>qalziet</strong> trousers.</li><li><strong>ġakketta</strong> jacket.</li><li><strong>kowt</strong> coat.</li><li><strong>flokk</strong> top, t-shirt.</li><li><strong>ingravata</strong> tie.</li><li><strong>żarbun</strong> shoes.</li><li><strong>buż</strong> boots.</li><li><strong>sandli</strong> sandals.</li><li><strong>kpiepel</strong> hat.</li><li><strong>xalla</strong> scarf / shawl.</li><li><strong>kalzetti</strong> socks.</li><li><strong>ħwejjeġ ta’ taħt</strong> underwear.</li></ul><h3 id="speaking-task-one-what-to-wear" tabindex="-1">Speaking Task One: What to Wear <a class="header-anchor" href="#speaking-task-one-what-to-wear" aria-label="Permalink to &quot;Speaking Task One: What to Wear&quot;">​</a></h3><p><strong>X’se tilbes biex...?</strong> (What will you wear to...?)</p><ul><li><strong>x’se tilbes</strong> what will you wear.</li><li><strong>biex</strong> to (purpose).</li><li><strong>tmur</strong> you go.</li><li><strong>jien</strong> I.</li><li><strong>nilbes</strong> I wear; distinct from &quot;you wear&quot; tilbes.</li></ul><table><thead><tr><th>Situation and reference answer</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Ix-xogħol? — Jien se nilbes qmis u qalziet għax-xogħol.</td><td>Work? — I&#39;ll wear a shirt and trousers for work.<br><strong>ix-xogħol</strong> work<br><strong>jien se nilbes</strong> I will wear<br><strong>qmis</strong> shirt<br><strong>u</strong> and<br><strong>qalziet</strong> trousers<br><strong>għax-xogħol</strong> to work (għal + article; not &quot;because of work&quot;).</td></tr><tr><td>Il-baħar? — Jien se nilbes malja u sandli biex immur il-baħar.</td><td>The beach? — I&#39;ll wear a swimsuit and sandals to go to the beach.<br><strong>il-baħar</strong> the sea/beach<br><strong>malja</strong> swimsuit<br><strong>sandli</strong> sandals<br><strong>biex</strong> to<br><strong>immur</strong> I go.</td></tr><tr><td>Xi tieġ jew okkażjoni speċjali? — Jien se nilbes libsa sabiħa għal tieġ.</td><td>A wedding or special occasion? — I&#39;ll wear a nice dress for the wedding.<br><strong>xi</strong> some<br><strong>tieġ</strong> wedding<br><strong>jew</strong> or<br><strong>okkażjoni speċjali</strong> special occasion<br><strong>libsa sabiħa</strong> a nice dress<br><strong>għal tieġ</strong> for a wedding.</td></tr><tr><td>Tiekol f’restorant? — Jien se nilbes qmis u ġakketta biex immur niekol f’restorant.</td><td>Eating at a restaurant? — I&#39;ll wear a shirt and jacket to go and eat at a restaurant.<br><strong>tiekol</strong> you eat<br><strong>f’restorant</strong> at a restaurant<br><strong>ġakketta</strong> jacket<br><strong>biex immur</strong> to go<br><strong>niekol</strong> I eat.</td></tr></tbody></table><h3 id="speaking-task-two-what-to-buy" tabindex="-1">Speaking Task Two: What to Buy <a class="header-anchor" href="#speaking-task-two-what-to-buy" aria-label="Permalink to &quot;Speaking Task Two: What to Buy&quot;">​</a></h3><p><strong>X’se tixtri mis-supermarket biex...? (Jien se nixtri...)</strong></p><ul><li><strong>x’se tixtri</strong> what will you buy.</li><li><strong>mis-supermarket</strong> from the supermarket.</li><li><strong>biex</strong> to (purpose).</li><li><strong>jien se nixtri</strong> I will buy.</li></ul><table><thead><tr><th>Question and reference answer</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Tipprepara xi ħaġa ħafifa għall-brejk tax-xogħol? — Jien se nixtri ħobż, ġobon u tadam biex nipprepara ftira.</td><td>Preparing something light for the work break? — I&#39;ll buy bread, cheese and tomatoes to make a ftira.<br><strong>tipprepara</strong> you prepare<br><strong>xi ħaġa</strong> something<br><strong>ħafifa</strong> light<br><strong>għall-brejk</strong> for the break<br><strong>tax-xogħol</strong> of work<br><strong>ħobż</strong> bread<br><strong>ġobon</strong> cheese<br><strong>tadam</strong> tomatoes<br><strong>biex nipprepara</strong> to prepare<br><strong>ftira</strong> Maltese flatbread / stuffed bread.</td></tr><tr><td>Issajjar l-ikla tal-Ħadd? — Jien se nixtri fenek, patata, basal u ħaxix biex insajjar stuffat tal-fenek.</td><td>Cooking Sunday lunch? — I&#39;ll buy rabbit, potatoes, onions and vegetables to make rabbit stew.<br><strong>issajjar</strong> you cook<br><strong>l-ikla</strong> the meal<br><strong>tal-Ħadd</strong> of Sunday<br><strong>fenek</strong> rabbit<br><strong>patata</strong> potatoes<br><strong>basal</strong> onions<br><strong>ħaxix</strong> vegetables<br><strong>biex insajjar</strong> to cook<br><strong>stuffat</strong> stew<br><strong>tal-fenek</strong> of rabbit.</td></tr></tbody></table><p>The second answer follows the example already given in the textbook and is not to be mistaken for a blank in the original exercise.</p><hr><h2 id="_4-fruit-and-vegetable-table-completion-and-word-notes" tabindex="-1">4 Fruit and Vegetable Table: Completion and Word Notes <a class="header-anchor" href="#_4-fruit-and-vegetable-table-completion-and-word-notes" aria-label="Permalink to &quot;4 Fruit and Vegetable Table: Completion and Word Notes&quot;">​</a></h2><p><strong>Il-frott u l-ħaxix</strong>: fruit and vegetables.</p><ul><li><strong>il-frott</strong> the fruit (collective noun).</li><li><strong>u</strong> and.</li><li><strong>l-ħaxix</strong> the vegetables (collective noun).</li></ul><p>This page is mainly a vocabulary matching exercise, one word/phrase per line; there is no need to force the items into sentences.</p><table><thead><tr><th>Original table word</th><th>Maltese reference answer</th><th>English and notes</th></tr></thead><tbody><tr><td>Cabbages</td><td><strong>kaboċċi</strong></td><td>cabbages; already given in the original table.</td></tr><tr><td>Onions</td><td><strong>basal</strong></td><td>onions; collective noun.</td></tr><tr><td>Garlic</td><td><strong>tewm</strong></td><td>garlic.</td></tr><tr><td>Potatoes</td><td><strong>patata</strong></td><td>potatoes.</td></tr><tr><td>Cucumbers</td><td><strong>ħjar</strong></td><td>cucumbers; a single one can be ħjara.</td></tr><tr><td>Cauliflower</td><td><strong>pastard</strong></td><td>cauliflower.</td></tr><tr><td>Beans</td><td><strong>fażola</strong></td><td>beans/legumes; broad beans are separately ful, a different kind.</td></tr><tr><td>Pumpkins</td><td><strong>qargħa aħmar</strong></td><td>the common expression for pumpkins.<br><strong>qargħa</strong> gourd<br><strong>aħmar</strong> red; remember the food name as a fixed combination.</td></tr><tr><td>Peas</td><td><strong>piżelli</strong></td><td>peas.</td></tr><tr><td>Mushrooms</td><td><strong>faqqiegħ</strong></td><td>mushrooms.</td></tr><tr><td>Carrots</td><td><strong>karrotti</strong></td><td>carrots; singular karrotta.</td></tr><tr><td>Lettuce</td><td><strong>ħass</strong></td><td>lettuce.</td></tr><tr><td>Bell Peppers</td><td><strong>bżar ħelu</strong></td><td>sweet peppers.<br><strong>bżar</strong> peppers<br><strong>ħelu</strong> sweet; often also distinguished by colour.</td></tr><tr><td>Spinich [original spelling]</td><td><strong>spinaċi</strong></td><td>spinach; the standard English spelling is &quot;spinach&quot;.</td></tr><tr><td>Oranges</td><td><strong>larinġ</strong></td><td>oranges; already given, refers to the collective.</td></tr><tr><td>Grapefruits</td><td><strong>grejpfrut</strong></td><td>grapefruit; a loanword, regional/dictionary variants exist.</td></tr><tr><td>Lemons</td><td><strong>lumi</strong></td><td>lemons; a single one can be lumija.</td></tr><tr><td>Apples</td><td><strong>tuffieħ</strong></td><td>apples (collective); a single one is tuffieħa.</td></tr><tr><td>Banana</td><td><strong>banana</strong></td><td>a banana; several can be banana as a collective or with a countable form, depending on context.</td></tr><tr><td>Pears</td><td><strong>lanġas</strong></td><td>pears (collective); a single one is lanġasa, countable plural lanġasiet.</td></tr><tr><td>Grapes</td><td><strong>għeneb</strong></td><td>grapes (collective).</td></tr><tr><td>Watermelons</td><td><strong>dulliegħ</strong></td><td>watermelons (collective); a single one is dulliegħa.</td></tr><tr><td>Melons</td><td><strong>bettieħ</strong></td><td>melons (collective); a single one is bettieħa.</td></tr><tr><td>Peaches</td><td><strong>ħawħ</strong></td><td>peaches (collective); a single one is ħawħa.</td></tr><tr><td>Plums</td><td><strong>għanbaqar</strong></td><td>plums (collective).</td></tr><tr><td>Strawberries</td><td><strong>frawli</strong></td><td>strawberries (collective).</td></tr><tr><td>Cherries</td><td><strong>ċirasa</strong></td><td>the common collective expression for cherries; the countable form depends on context.</td></tr><tr><td>Tadam [already Maltese in the original table]</td><td><strong>tadam</strong>; English: tomatoes</td><td>tomatoes (collective); a single one is tadama. Don&#39;t treat Tadam as an English word to be translated into Maltese.</td></tr></tbody></table><p><strong>Learning focus:</strong> fruit and vegetables often use collective nouns; &quot;a single one&quot; and &quot;as a food category&quot; do not always use the same form. Don&#39;t treat every collective noun as if it were an English-style plural.</p><hr><h2 id="_5-ingredient-notes-line-by-line" tabindex="-1">5 Ingredient Notes, Line by Line <a class="header-anchor" href="#_5-ingredient-notes-line-by-line" aria-label="Permalink to &quot;5 Ingredient Notes, Line by Line&quot;">​</a></h2><table><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Il-Qari – Aqra din ir-riċetta.</td><td>Reading: read this recipe.<br><strong>il-qari</strong> the reading<br><strong>aqra</strong> read<br><strong>din</strong> this (feminine)<br><strong>ir-riċetta</strong> the recipe.</td></tr><tr><td>Ir-riċetta tal-lum hija r-riċetta tal-kejk tal-Oreo.</td><td>Today&#39;s recipe is the Oreo cake recipe.<br><strong>ir-riċetta</strong> the recipe<br><strong>tal-lum</strong> of today<br><strong>hija</strong> is (feminine)<br><strong>tal-kejk</strong> of the cake<br><strong>tal-Oreo</strong> of Oreo.</td></tr><tr><td>L-ingredjenti li għandkom bżonn huma...</td><td>The ingredients you need are...<br><strong>l-ingredjenti</strong> the ingredients (plural)<br><strong>li</strong> that<br><strong>għandkom bżonn</strong> you need<br><strong>huma</strong> are (plural).</td></tr></tbody></table><h3 id="each-ingredient-word-and-quantity" tabindex="-1">Each Ingredient: Word and Quantity <a class="header-anchor" href="#each-ingredient-word-and-quantity" aria-label="Permalink to &quot;Each Ingredient: Word and Quantity&quot;">​</a></h3><table><thead><tr><th>Original amount</th><th>Written-out number</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>200g dqiq</td><td>mitejn gramma dqiq</td><td>200 g of flour.<br><strong>mitejn</strong> two hundred<br><strong>gramma</strong> gram<br><strong>dqiq</strong> flour.</td></tr><tr><td>280g zokkor</td><td>mitejn u tmenin gramma zokkor</td><td>280 g of sugar.<br><strong>mitejn</strong> two hundred<br><strong>u</strong> and<br><strong>tmenin</strong> eighty<br><strong>zokkor</strong> sugar.</td></tr><tr><td>40g trab taċ-ċikkulata</td><td>erbgħin gramma trab taċ-ċikkulata</td><td>40 g of cocoa powder.<br><strong>erbgħin</strong> forty<br><strong>trab</strong> powder<br><strong>taċ-ċikkulata</strong> of chocolate; in baking, understood by the ingredient name, not changed into another ingredient.</td></tr><tr><td>3 kuċċarini trab tal-ħami</td><td>tliet kuċċarini trab tal-ħami</td><td>three teaspoons of baking powder.<br><strong>tliet</strong> three (before a noun)<br><strong>kuċċarini</strong> teaspoons (plural)<br><strong>trab</strong> powder<br><strong>tal-ħami</strong> for baking.</td></tr><tr><td>Ftit melħ</td><td>ftit melħ</td><td>a little salt.<br><strong>ftit</strong> a little<br><strong>melħ</strong> salt.</td></tr><tr><td>80g butir mhux mielaħ</td><td>tmenin gramma butir mhux mielaħ</td><td>80 g of unsalted butter.<br><strong>tmenin</strong> eighty<br><strong>butir</strong> butter<br><strong>mhux</strong> not<br><strong>mielaħ</strong> salted.</td></tr><tr><td>240ml ħalib</td><td>mitejn u erbgħin millilitru ħalib</td><td>240 ml of milk.<br><strong>mitejn</strong> two hundred<br><strong>u erbgħin</strong> plus forty<br><strong>millilitru</strong> millilitre<br><strong>ħalib</strong> milk.</td></tr><tr><td>3 bajdiet</td><td>tliet bajdiet</td><td>three eggs.<br><strong>tliet</strong> three<br><strong>bajdiet</strong> countable eggs (plural); the collective noun is bajd.</td></tr><tr><td>½ kuċċarina essenza tal-vanilla</td><td>nofs kuċċarina essenza tal-vanilla</td><td>half a teaspoon of vanilla essence.<br><strong>nofs</strong> half<br><strong>kuċċarina</strong> teaspoon (singular)<br><strong>essenza</strong> essence<br><strong>tal-vanilla</strong> of vanilla.</td></tr><tr><td>12-il gallettina tal-Oreo</td><td>tnax-il gallettina tal-Oreo</td><td>twelve Oreo biscuits.<br><strong>tnax-il</strong> twelve, form used before a noun<br><strong>gallettina</strong> biscuit (singular in this structure)<br><strong>tal-Oreo</strong> of the Oreo brand.</td></tr></tbody></table><hr><h2 id="_6-exercise-analysis" tabindex="-1">6 Exercise Analysis <a class="header-anchor" href="#_6-exercise-analysis" aria-label="Permalink to &quot;6 Exercise Analysis&quot;">​</a></h2><p><strong>Imla l-vojt bin-numri fi kliem, skont kif mitlub u skont l-ingredjenti li hemm fir-riċetta.</strong></p><p>Fill in the blanks by writing the numbers in words, as required and according to the ingredients in the recipe.</p><ul><li><strong>imla l-vojt</strong> fill in the blank.</li><li><strong>bin-numri</strong> with the numbers.</li><li><strong>fi kliem</strong> in words.</li><li><strong>skont</strong> according to.</li><li><strong>kif mitlub</strong> as required.</li><li><strong>u</strong> and.</li><li><strong>l-ingredjenti</strong> the ingredients.</li><li><strong>li hemm</strong> that there are, listed.</li><li><strong>fir-riċetta</strong> in the recipe.</li></ul><h3 id="completed-steps-and-sentence-by-sentence-analysis" tabindex="-1">Completed Steps and Sentence-by-Sentence Analysis <a class="header-anchor" href="#completed-steps-and-sentence-by-sentence-analysis" aria-label="Permalink to &quot;Completed Steps and Sentence-by-Sentence Analysis&quot;">​</a></h3><p><strong>Il-metodu — L-ewwel pass</strong>: the method — first step.</p><ul><li><strong>il-metodu</strong> the method.</li><li><strong>l-ewwel</strong> first.</li><li><strong>pass</strong> step.</li></ul><table><thead><tr><th>Completed sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Ixgħel il-forn minn qabel fuq it-temperatura ta’ 170°C — mija u sebgħin grad Celsius.</td><td>Preheat the oven to 170°C.<br><strong>ixgħel</strong> switch on (imperative)<br><strong>il-forn</strong> the oven<br><strong>minn qabel</strong> in advance<br><strong>fuq</strong> set at<br><strong>it-temperatura</strong> the temperature<br><strong>ta’</strong> of<br><strong>mija u sebgħin</strong> one hundred and seventy<br><strong>grad Celsius</strong> degrees Celsius.</td></tr><tr><td>Itfa’ mitejn gramma dqiq, mitejn u tmenin gramma zokkor, erbgħin gramma trab taċ-ċikkulata, tliet kuċċarini trab tal-ħami, ftit melħ u tmenin gramma butir fi skutella kbira.</td><td>Put 200 g of flour, 280 g of sugar, 40 g of cocoa powder, three teaspoons of baking powder, a little salt and 80 g of butter into a large bowl.<br><strong>itfa’</strong> put in<br><strong>mitejn gramma dqiq</strong> 200 g of flour<br><strong>mitejn u tmenin gramma zokkor</strong> 280 g of sugar<br><strong>erbgħin gramma</strong> 40 g<br><strong>trab taċ-ċikkulata</strong> cocoa powder<br><strong>tliet kuċċarini</strong> three teaspoons<br><strong>trab tal-ħami</strong> baking powder<br><strong>ftit melħ</strong> a little salt<br><strong>u</strong> and<br><strong>tmenin gramma butir</strong> 80 g of butter<br><strong>fi skutella</strong> in a bowl<br><strong>kbira</strong> big (feminine).</td></tr><tr><td>Ħawwad sakemm ikollok konsistenza tajba.</td><td>Stir until you have a good consistency.<br><strong>ħawwad</strong> stir<br><strong>sakemm</strong> until<br><strong>ikollok</strong> you get/have<br><strong>konsistenza</strong> consistency, texture<br><strong>tajba</strong> good, right.</td></tr></tbody></table><p><strong>It-tieni pass</strong>: the second step.</p><ul><li><strong>it-tieni</strong> second.</li><li><strong>pass</strong> step.</li></ul><table><thead><tr><th>Completed sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Ħawwad mitejn u erbgħin millilitru ħalib, tliet bajdiet u nofs kuċċarina essenza tal-vanilla flimkien ġewwa kontenitur.</td><td>Mix 240 ml of milk, three eggs and half a teaspoon of vanilla essence together in a container.<br><strong>ħawwad</strong> mix<br><strong>mitejn u erbgħin millilitru</strong> 240 ml<br><strong>ħalib</strong> milk<br><strong>tliet bajdiet</strong> three eggs<br><strong>u</strong> and<br><strong>nofs kuċċarina</strong> half a teaspoon<br><strong>essenza tal-vanilla</strong> vanilla essence<br><strong>flimkien</strong> together<br><strong>ġewwa</strong> inside<br><strong>kontenitur</strong> container.</td></tr><tr><td>Wara żid din it-taħlita bil-mod, fit-taħlita tad-dqiq u ħawwad sew. (Li tkun għamilt qabel).</td><td>Then slowly add this mixture to the flour mixture you made earlier, and mix well. The brackets are an added note in the original; as a standalone clause it is incomplete.<br><strong>wara</strong> after<br><strong>żid</strong> add<br><strong>din</strong> this<br><strong>it-taħlita</strong> the mixture<br><strong>bil-mod</strong> slowly<br><strong>fit-taħlita</strong> into the mixture<br><strong>tad-dqiq</strong> of flour<br><strong>u</strong> and<br><strong>ħawwad sew</strong> mix well<br><strong>li</strong> that<br><strong>tkun għamilt</strong> you have made<br><strong>qabel</strong> before.</td></tr><tr><td>Farrak tnax-il gallettina tal-Oreo ġewwa din it-taħlita u ħawwadha magħhom.</td><td>Crush twelve Oreo biscuits into this mixture and stir them in.<br><strong>farrak</strong> crush<br><strong>tnax-il</strong> twelve (before a noun)<br><strong>gallettina tal-Oreo</strong> Oreo biscuit<br><strong>ġewwa din it-taħlita</strong> in this mixture<br><strong>u</strong> and<br><strong>ħawwadha</strong> stir it (-ha refers to the feminine taħlita)<br><strong>magħhom</strong> with them.</td></tr></tbody></table><p><strong>It-tielet pass</strong>: the third step.</p><ul><li><strong>it-tielet</strong> third.</li><li><strong>pass</strong> step.</li></ul><table><thead><tr><th>Completed sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Ifrex din it-taħlita f’kontenitur tond b’dijametru ta’ ħamsa u għoxrin ċentimetru li qabel tkun dlikt bil-butir sabiex tevita li jeħel dan il-kejk.</td><td>Spread this mixture in a round container 25 cm in diameter that you have buttered in advance, so that this cake doesn&#39;t stick.<br><strong>ifrex</strong> spread out<br><strong>din it-taħlita</strong> this mixture<br><strong>f’kontenitur</strong> in a container<br><strong>tond</strong> round<br><strong>b’dijametru</strong> with a diameter<br><strong>ta’</strong> of<br><strong>ħamsa u għoxrin</strong> twenty-five<br><strong>ċentimetru</strong> centimetre<br><strong>li</strong> that<br><strong>qabel</strong> in advance<br><strong>tkun dlikt</strong> you have spread/buttered<br><strong>bil-butir</strong> with butter<br><strong>sabiex</strong> so that<br><strong>tevita</strong> you avoid<br><strong>li jeħel</strong> it sticks<br><strong>dan il-kejk</strong> this cake.</td></tr></tbody></table><p><strong>Ir-raba’ pass</strong>: the fourth step.</p><ul><li><strong>ir-raba’</strong> fourth; don&#39;t confuse with the cardinal erba’.</li><li><strong>pass</strong> step.</li></ul><table><thead><tr><th>Completed sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Aħmi l-kejk tal-Oreo ġewwa l-forn għal madwar tletin minuta.</td><td>Bake the Oreo cake in the oven for about thirty minutes.<br><strong>aħmi</strong> bake<br><strong>l-kejk tal-Oreo</strong> the Oreo cake<br><strong>ġewwa l-forn</strong> in the oven<br><strong>għal</strong> for (duration)<br><strong>madwar</strong> about<br><strong>tletin</strong> thirty<br><strong>minuta</strong> minutes (singular in this counting structure).</td></tr><tr><td>Wara oħroġ il-kejk, aqsmu u kulu!</td><td>Then take the cake out, cut it up and eat it!<br><strong>wara</strong> then<br><strong>oħroġ</strong> take out<br><strong>il-kejk</strong> the cake<br><strong>aqsmu</strong> cut it (aqsam + object -u)<br><strong>u</strong> and<br><strong>kulu</strong> eat it (understood with object -u; don&#39;t read -u as &quot;you-plural&quot; everywhere).</td></tr></tbody></table><hr><h2 id="_7-imperative-instructions-line-by-line" tabindex="-1">7 Imperative Instructions, Line by Line <a class="header-anchor" href="#_7-imperative-instructions-line-by-line" aria-label="Permalink to &quot;7 Imperative Instructions, Line by Line&quot;">​</a></h2><table><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>L-Imperattiv – Il-Kmand</td><td>The imperative — the command.<br><strong>l-imperattiv</strong> the imperative<br><strong>il-kmand</strong> the command.</td></tr><tr><td>X’qed tinnota dwar il-verbi li huma mmarkati bil-grassett f’paġna ?</td><td>What do you notice about the verbs marked in bold on the page? The page number is blank in the original; by context it refers to the recipe steps.<br><strong>x’</strong> what<br><strong>qed</strong> -ing<br><strong>tinnota</strong> you notice<br><strong>dwar</strong> about<br><strong>il-verbi</strong> the verbs<br><strong>li huma</strong> that are<br><strong>mmarkati</strong> marked<br><strong>bil-grassett</strong> in bold<br><strong>f’paġna</strong> on a page.</td></tr><tr><td>Dan jintuża meta tikkmanda lil xi ħadd, jew titlob xi ħaġa lil xi ħadd.</td><td>It is used when you command someone, or ask something of someone.<br><strong>dan</strong> this (the imperative)<br><strong>jintuża</strong> is used<br><strong>meta</strong> when<br><strong>tikkmanda</strong> you command<br><strong>lil xi ħadd</strong> someone (object)<br><strong>jew</strong> or<br><strong>titlob</strong> you ask<br><strong>xi ħaġa</strong> something<br><strong>lil xi ħadd</strong> of someone.</td></tr><tr><td>Ħares lejn dawn il-verbi fl-imperattiv u ikteb sentenza bihom.</td><td>Look at these imperative verbs and write a sentence with each.<br><strong>ħares lejn</strong> look at<br><strong>dawn il-verbi</strong> these verbs<br><strong>fl-imperattiv</strong> in the imperative<br><strong>u</strong> and<br><strong>ikteb</strong> write<br><strong>sentenza</strong> a sentence<br><strong>bihom</strong> with them.</td></tr></tbody></table><p>Reference answer for the observation: <strong>Dawn il-verbi jagħtu kmand jew struzzjoni.</strong> These verbs give a command or an instruction.</p><ul><li><strong>dawn il-verbi</strong> these verbs.</li><li><strong>jagħtu</strong> they give.</li><li><strong>kmand</strong> command.</li><li><strong>jew</strong> or.</li><li><strong>struzzjoni</strong> instruction.</li></ul><h3 id="reference-sentences-for-all-of-1–21" tabindex="-1">Reference Sentences for All of 1–21 <a class="header-anchor" href="#reference-sentences-for-all-of-1–21" aria-label="Permalink to &quot;Reference Sentences for All of 1–21&quot;">​</a></h3><table><thead><tr><th>Verb and reference sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Agħti — Agħti l-ktieb lil Marija.</td><td>Give the book to Marija.<br><strong>agħti</strong> give<br><strong>l-ktieb</strong> the book<br><strong>lil Marija</strong> to Marija.</td></tr><tr><td>2. Ilbes — Ilbes il-kowt.</td><td>Put on the coat.<br><strong>ilbes</strong> put on<br><strong>il-kowt</strong> the coat.</td></tr><tr><td>3. Agħmel — Agħmel l-eżerċizzju.</td><td>Do the exercise.<br><strong>agħmel</strong> do<br><strong>l-eżerċizzju</strong> the exercise.</td></tr><tr><td>4. Ersaq — Ersaq hawn.</td><td>Come here.<br><strong>ersaq</strong> approach, come<br><strong>hawn</strong> here.</td></tr><tr><td>5. Irkeb — Irkeb il-karozza tal-linja.</td><td>Get on the bus.<br><strong>irkeb</strong> ride, board<br><strong>il-karozza tal-linja</strong> the bus.</td></tr><tr><td>6. Iftaħ — Iftaħ il-bieb.</td><td>Open the door.<br><strong>iftaħ</strong> open<br><strong>il-bieb</strong> the door.</td></tr><tr><td>7. Agħlaq — Agħlaq it-tieqa.</td><td>Close the window.<br><strong>agħlaq</strong> close<br><strong>it-tieqa</strong> the window.</td></tr><tr><td>8. Ieqaf — Ieqaf hawn.</td><td>Stop here.<br><strong>ieqaf</strong> stop<br><strong>hawn</strong> here.</td></tr><tr><td>9. Kul — Kul it-tuffieħa.</td><td>Eat the apple.<br><strong>kul</strong> eat<br><strong>it-tuffieħa</strong> the apple.</td></tr><tr><td>10. Aħsel — Aħsel idejk.</td><td>Wash your hands.<br><strong>aħsel</strong> wash<br><strong>idejk</strong> your hands (dual + possessive).</td></tr><tr><td>11. Aqbad — Aqbad il-ballun.</td><td>Catch the ball.<br><strong>aqbad</strong> grab, catch<br><strong>il-ballun</strong> the ball.</td></tr><tr><td>12. Itfa’ — Itfa’ z-zokkor fl-iskutella.</td><td>Put the sugar into the bowl.<br><strong>itfa’</strong> put in<br><strong>z-zokkor</strong> the sugar<br><strong>fl-iskutella</strong> in the bowl.</td></tr><tr><td>13. Sajjar — Sajjar l-ikla.</td><td>Cook the meal.<br><strong>sajjar</strong> cook<br><strong>l-ikla</strong> the meal.</td></tr><tr><td>14. Qatta’ — Qatta’ l-basal.</td><td>Chop the onions.<br><strong>qatta’</strong> chop<br><strong>l-basal</strong> the onions.</td></tr><tr><td>15. Aħmi — Aħmi l-kejk.</td><td>Bake the cake.<br><strong>aħmi</strong> bake<br><strong>l-kejk</strong> the cake.</td></tr><tr><td>16. Ħawwad — Ħawwad it-taħlita.</td><td>Stir the mixture.<br><strong>ħawwad</strong> stir<br><strong>it-taħlita</strong> the mixture.</td></tr><tr><td>17. Dawwar — Dawwar il-paġna.</td><td>Turn the page.<br><strong>dawwar</strong> turn<br><strong>il-paġna</strong> the page.</td></tr><tr><td>18. Ħallas — Ħallas il-kont.</td><td>Pay the bill.<br><strong>ħallas</strong> pay<br><strong>il-kont</strong> the bill.</td></tr><tr><td>19. Farfar — Farfar il-mejda.</td><td>Dust the table.<br><strong>farfar</strong> dust<br><strong>il-mejda</strong> the table.</td></tr><tr><td>20. Ċapċap — Ċapċap għalihom.</td><td>Clap for them.<br><strong>ċapċap</strong> clap<br><strong>għalihom</strong> for them.</td></tr><tr><td>21. Farfar — Farfar l-ixkaffa.</td><td>Dust the shelf.<br><strong>farfar</strong> dust; the original repeats this verb, another sentence is made here<br><strong>l-ixkaffa</strong> the shelf.</td></tr></tbody></table><hr><h2 id="_8-answers-for-sentences-22–30" tabindex="-1">8 Answers for Sentences 22–30 <a class="header-anchor" href="#_8-answers-for-sentences-22–30" aria-label="Permalink to &quot;8 Answers for Sentences 22–30&quot;">​</a></h2><table><thead><tr><th>Verb and reference sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>22. Kompli — Kompli l-eżerċizzju.</td><td>Continue the exercise.<br><strong>kompli</strong> continue, carry on<br><strong>l-eżerċizzju</strong> the exercise.</td></tr><tr><td>23. Irranġa — Irranġa l-kamra.</td><td>Tidy the room.<br><strong>irranġa</strong> tidy, arrange, repair<br><strong>l-kamra</strong> the room.</td></tr><tr><td>24. Irritorna — Irritorna l-ktieb.</td><td>Return the book.<br><strong>irritorna</strong> return<br><strong>l-ktieb</strong> the book.</td></tr><tr><td>25. Ipprova — Ipprova din il-libsa.</td><td>Try on this dress.<br><strong>ipprova</strong> try<br><strong>din</strong> this<br><strong>il-libsa</strong> the dress.</td></tr><tr><td>26. Ifforma — Ifforma sentenza.</td><td>Form a sentence.<br><strong>ifforma</strong> form<br><strong>sentenza</strong> sentence.</td></tr><tr><td>27. Ipprintja — Ipprintja d-dokument.</td><td>Print the document.<br><strong>ipprintja</strong> print<br><strong>d-dokument</strong> the document.</td></tr><tr><td>28. Ipparkja — Ipparkja l-karozza hawn.</td><td>Park the car here.<br><strong>ipparkja</strong> park<br><strong>l-karozza</strong> the car<br><strong>hawn</strong> here.</td></tr><tr><td>29. Iffajlja — Iffajlja d-dokument.</td><td>File the document.<br><strong>iffajlja</strong> file, archive<br><strong>d-dokument</strong> the document.</td></tr><tr><td>30. Ibbukkja — Ibbukkja mejda għal tnejn.</td><td>Book a table for two.<br><strong>ibbukkja</strong> book<br><strong>mejda</strong> table<br><strong>għal</strong> for<br><strong>tnejn</strong> two people; the full cardinal is used independently here.</td></tr></tbody></table><h3 id="understanding-the-etymology-notes-line-by-line" tabindex="-1">Understanding the Etymology Notes, Line by Line <a class="header-anchor" href="#understanding-the-etymology-notes-line-by-line" aria-label="Permalink to &quot;Understanding the Etymology Notes, Line by Line&quot;">​</a></h3><table><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Il-verbi kollha ta’ paġna 5 huma Semitiċi, jiġifieri ġejjin mill-Għarbi.</td><td>&quot;All the verbs on page 5 are Semitic, that is, they come from Arabic.&quot; This is the textbook&#39;s original sentence; the page reference does not match this PDF.<br><strong>il-verbi</strong> the verbs<br><strong>kollha</strong> all<br><strong>ta’ paġna 5</strong> of page 5<br><strong>huma</strong> are<br><strong>Semitiċi</strong> Semitic<br><strong>jiġifieri</strong> that is<br><strong>ġejjin</strong> come from (plural)<br><strong>mill-Għarbi</strong> from Arabic.</td></tr><tr><td>Il-verbi ta’ dil-paġna mhumiex Semitiċi, iżda huma Rumanzi (Taljani) u Ingliżi.</td><td>&quot;The verbs on this page are not Semitic but Romance (Italian) and English.&quot; This is a teaching generalisation; it isn&#39;t enough to determine etymology word by word.<br><strong>il-verbi</strong> the verbs<br><strong>ta’ dil-paġna</strong> of this page<br><strong>mhumiex</strong> they are not<br><strong>Semitiċi</strong> Semitic<br><strong>iżda</strong> but, rather<br><strong>huma</strong> they are<br><strong>Rumanzi</strong> Romance<br><strong>Taljani</strong> Italian<br><strong>u</strong> and<br><strong>Ingliżi</strong> English.</td></tr><tr><td>Ikteb x’inhuma libsin dawn in-nies.</td><td>Write what these people are wearing.<br><strong>ikteb</strong> write<br><strong>x’inhuma</strong> what they are<br><strong>libsin</strong> wearing (plural)<br><strong>dawn</strong> these<br><strong>in-nies</strong> the people.</td></tr></tbody></table><h3 id="the-woman-s-photo-reference-paragraph" tabindex="-1">The Woman&#39;s Photo: Reference Paragraph <a class="header-anchor" href="#the-woman-s-photo-reference-paragraph" aria-label="Permalink to &quot;The Woman&#39;s Photo: Reference Paragraph&quot;">​</a></h3><blockquote><p>Il-mara liebsa flokk abjad, xorts tal-ġins u ġakketta bil-fjuri. Għandha nuċċali u ġiżirana twila.</p></blockquote><p>English: the woman is wearing a white top, denim shorts and a floral jacket; she has glasses and a long necklace. The clothing categories are general descriptions based on the photo; no brand is inferred.</p><ul><li><strong>il-mara</strong> the woman.</li><li><strong>liebsa</strong> wearing (feminine singular).</li><li><strong>flokk</strong> top.</li><li><strong>abjad</strong> white.</li><li><strong>xorts</strong> shorts.</li><li><strong>tal-ġins</strong> denim.</li><li><strong>u</strong> and.</li><li><strong>ġakketta</strong> jacket.</li><li><strong>bil-fjuri</strong> with floral pattern.</li><li><strong>għandha</strong> she has, she is wearing.</li><li><strong>nuċċali</strong> glasses.</li><li><strong>ġiżirana</strong> necklace.</li><li><strong>twila</strong> long (feminine).</li></ul><hr><h2 id="_9-the-man-s-photo-reference-paragraph" tabindex="-1">9 The Man&#39;s Photo: Reference Paragraph <a class="header-anchor" href="#_9-the-man-s-photo-reference-paragraph" aria-label="Permalink to &quot;9 The Man&#39;s Photo: Reference Paragraph&quot;">​</a></h2><blockquote><p>Ir-raġel liebes libsa skura, qmis ċara u ingravata. Għandu żarbun kannella.</p></blockquote><p>English: the man is wearing a dark suit, a light shirt and a tie, and brown shoes.</p><ul><li><strong>ir-raġel</strong> the man.</li><li><strong>liebes</strong> wearing (masculine singular).</li><li><strong>libsa</strong> a suit (here, a suit).</li><li><strong>skura</strong> dark (with feminine libsa).</li><li><strong>qmis</strong> shirt.</li><li><strong>ċara</strong> light.</li><li><strong>u</strong> and.</li><li><strong>ingravata</strong> tie.</li><li><strong>għandu</strong> he has, he is wearing.</li><li><strong>żarbun</strong> shoes.</li><li><strong>kannella</strong> brown.</li></ul><h3 id="the-eight-person-illustration-exercise-and-answers" tabindex="-1">The Eight-Person Illustration: Exercise and Answers <a class="header-anchor" href="#the-eight-person-illustration-exercise-and-answers" aria-label="Permalink to &quot;The Eight-Person Illustration: Exercise and Answers&quot;">​</a></h3><p><strong>X’inhuma lebsin? Ikteb in-numru fil-kaxxa t-tajba.</strong> What are they wearing? Write the number in the correct box.</p><ul><li><strong>x’inhuma lebsin</strong> what are they wearing; read alongside libsin on the previous page, both as in the material.</li><li><strong>ikteb</strong> write.</li><li><strong>in-numru</strong> the number.</li><li><strong>fil-kaxxa</strong> in the box.</li><li><strong>t-tajba</strong> the correct.</li></ul><p>From left to right the illustration reads: <strong>6, 3, 1, 2, 7, 5, 8, 4</strong>.</p><table><thead><tr><th>Person&#39;s original sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Marija liebsa flokk biċ-ċingi vjola, ġins u żarbun tat-takkuna kannella. Għandha wkoll ċintorin kannella.</td><td>Marija is wearing a purple strappy top, jeans and brown heeled shoes, plus a brown belt.<br><strong>Marija</strong> a name<br><strong>liebsa</strong> wearing (f)<br><strong>flokk</strong> top<br><strong>biċ-ċingi</strong> with straps<br><strong>vjola</strong> purple<br><strong>ġins</strong> jeans<br><strong>u</strong> and<br><strong>żarbun tat-takkuna</strong> heeled shoes<br><strong>kannella</strong> brown<br><strong>għandha</strong> she has / is wearing<br><strong>wkoll</strong> also<br><strong>ċintorin</strong> belt.</td></tr><tr><td>2. Toni liebes flokk bil-komma qasira aħmar, ġins, ċintorin iswed u żarbun kannella.</td><td>Toni is wearing a red short-sleeved top, jeans, a black belt and brown shoes.<br><strong>Toni</strong> a name<br><strong>liebes</strong> wearing (m)<br><strong>flokk</strong> top<br><strong>bil-komma</strong> with sleeves<br><strong>qasira</strong> short (modifying komma)<br><strong>aħmar</strong> red (modifying flokk)<br><strong>ġins</strong> jeans<br><strong>ċintorin</strong> belt<br><strong>iswed</strong> black<br><strong>u</strong> and<br><strong>żarbun kannella</strong> brown shoes.</td></tr><tr><td>3. Lina liebsa flokk aħdar, qalziet griż u żarbun iswed.</td><td>Lina is wearing a green top, grey trousers and black shoes.<br><strong>Lina</strong> a name<br><strong>liebsa</strong> wearing<br><strong>flokk aħdar</strong> green top<br><strong>qalziet griż</strong> grey trousers<br><strong>u</strong> and<br><strong>żarbun iswed</strong> black shoes.</td></tr><tr><td>4. Fredu liebes qalziet aħdar, qmis, ġakketta tal-ġins u żarbun iswed. Taħt il-qmis għandu flokk abjad.</td><td>Fredu is wearing green trousers, a shirt, a denim jacket and black shoes; under the shirt he has a white top.<br><strong>Fredu</strong> a name<br><strong>liebes</strong> wearing<br><strong>qalziet aħdar</strong> green trousers<br><strong>qmis</strong> shirt<br><strong>ġakketta tal-ġins</strong> denim jacket<br><strong>u</strong> and<br><strong>żarbun iswed</strong> black shoes<br><strong>taħt</strong> under<br><strong>il-qmis</strong> the shirt<br><strong>għandu</strong> he has / is wearing<br><strong>flokk abjad</strong> white top.</td></tr><tr><td>5. Luċija liebsa blaws griż, dublett blu ċar, tajz trasparenti, żarbun tat-takkuna kannella u ġiżirana.</td><td>Luċija is wearing a grey blouse, a light blue skirt, sheer tights, brown heeled shoes and a necklace.<br><strong>Luċija</strong> a name<br><strong>liebsa</strong> wearing<br><strong>blaws</strong> blouse<br><strong>griż</strong> grey<br><strong>dublett</strong> skirt<br><strong>blu ċar</strong> light blue<br><strong>tajz</strong> tights<br><strong>trasparenti</strong> sheer<br><strong>żarbun tat-takkuna</strong> heeled shoes<br><strong>kannella</strong> brown<br><strong>u</strong> and<br><strong>ġiżirana</strong> necklace.</td></tr><tr><td>6. Pawlu liebes flokk tal-komma qasira aħdar, ġins blu u żarbun kannella.</td><td>Pawlu is wearing a green short-sleeved top, blue jeans and brown shoes.<br><strong>Pawlu</strong> a name<br><strong>liebes</strong> wearing<br><strong>flokk</strong> top<br><strong>tal-komma qasira</strong> short-sleeved<br><strong>aħdar</strong> green<br><strong>ġins blu</strong> blue jeans<br><strong>u</strong> and<br><strong>żarbun kannella</strong> brown shoes.</td></tr><tr><td>7. Kristina għandha flokk biċ-ċingi aħdar, qalziet blu u fuqu dublett roża. Liebsa wkoll buż blu.</td><td>Kristina is wearing a green strappy top and blue trousers, with a pink skirt over them, and blue boots as well.<br><strong>Kristina</strong> a name<br><strong>għandha</strong> she has / is wearing<br><strong>flokk biċ-ċingi</strong> strappy top<br><strong>aħdar</strong> green<br><strong>qalziet blu</strong> blue trousers<br><strong>u</strong> and<br><strong>fuqu</strong> over it (the trousers)<br><strong>dublett roża</strong> pink skirt<br><strong>liebsa</strong> wearing<br><strong>wkoll</strong> also<br><strong>buż blu</strong> blue boots.</td></tr><tr><td>8. Rita liebsa flokk aħdar bil-komma qasira. Fuqu għandha flokk taċ-ċingi blu. Liebsa wkoll qalziet griż u żarbun iswed.</td><td>Rita is wearing a green short-sleeved top with a blue strappy top over it, plus grey trousers and black shoes.<br><strong>Rita</strong> a name<br><strong>liebsa</strong> wearing<br><strong>flokk aħdar</strong> green top<br><strong>bil-komma qasira</strong> short-sleeved<br><strong>fuqu</strong> over it<br><strong>għandha</strong> she has / is wearing<br><strong>flokk taċ-ċingi blu</strong> blue strappy top<br><strong>wkoll</strong> also<br><strong>qalziet griż</strong> grey trousers<br><strong>u</strong> and<br><strong>żarbun iswed</strong> black shoes.</td></tr></tbody></table><p>Source caption <strong>Il-Malti bħala lingwa barranija</strong>: Maltese as a foreign language.</p><ul><li><strong>il-Malti</strong> Maltese.</li><li><strong>bħala</strong> as.</li><li><strong>lingwa</strong> language.</li><li><strong>barranija</strong> foreign (feminine).</li><li><strong>Stephanie Dempsey</strong> the original illustrator&#39;s credit.</li></ul><hr><h2 id="_10-a-reading-1–20" tabindex="-1">10 A. Reading 1–20 <a class="header-anchor" href="#_10-a-reading-1–20" aria-label="Permalink to &quot;10 A. Reading 1–20&quot;">​</a></h2><p><strong>In-numri bil-Malti</strong>: the numbers in Maltese.</p><ul><li><strong>in-numri</strong> the numbers.</li><li><strong>bil-Malti</strong> in Maltese.</li></ul><table><thead><tr><th>Number</th><th>Maltese and English</th><th>Number</th><th>Maltese and English</th></tr></thead><tbody><tr><td>1</td><td><strong>wieħed</strong> one (standalone / masculine)</td><td>11</td><td><strong>ħdax</strong> eleven</td></tr><tr><td>2</td><td><strong>tnejn</strong> two</td><td>12</td><td><strong>tnax</strong> twelve</td></tr><tr><td>3</td><td><strong>tlieta</strong> three</td><td>13</td><td><strong>tlettax</strong> thirteen</td></tr><tr><td>4</td><td><strong>erbgħa</strong> four</td><td>14</td><td><strong>erbatax</strong> fourteen</td></tr><tr><td>5</td><td><strong>ħamsa</strong> five</td><td>15</td><td><strong>ħmistax</strong> fifteen</td></tr><tr><td>6</td><td><strong>sitta</strong> six</td><td>16</td><td><strong>sittax</strong> sixteen</td></tr><tr><td>7</td><td><strong>sebgħa</strong> seven</td><td>17</td><td><strong>sbatax</strong> seventeen</td></tr><tr><td>8</td><td><strong>tmienja</strong> eight</td><td>18</td><td><strong>tmintax</strong> eighteen</td></tr><tr><td>9</td><td><strong>disgħa</strong> nine</td><td>19</td><td><strong>dsatax</strong> nineteen</td></tr><tr><td>10</td><td><strong>għaxra</strong> ten</td><td>20</td><td><strong>għoxrin</strong> twenty</td></tr></tbody></table><p>These are the standalone reading forms; don&#39;t write <code>erbgħa</code> as <code>erba’</code> in every position — the latter is the form used before a noun.</p><h3 id="b-number-bingo-listening" tabindex="-1">B. Number Bingo Listening <a class="header-anchor" href="#b-number-bingo-listening" aria-label="Permalink to &quot;B. Number Bingo Listening&quot;">​</a></h3><p><strong>Ejjew nilagħbu ftit tombla! Immarka n-numru li tisma’.</strong></p><p>Let&#39;s play a bit of bingo! Mark the number you hear.</p><ul><li><strong>ejjew</strong> come on (to several people).</li><li><strong>nilagħbu</strong> we play.</li><li><strong>ftit</strong> a bit.</li><li><strong>tombla</strong> bingo / number-draw game.</li><li><strong>immarka</strong> mark.</li><li><strong>n-numru</strong> the number.</li><li><strong>li tisma’</strong> that you hear.</li></ul><p><strong>Answer status: no recording available, so it cannot be determined which squares to mark.</strong> The empty squares are part of the bingo layout, not homework blanks to be filled with numbers.</p><h3 id="c-phone-numbers" tabindex="-1">C. Phone Numbers <a class="header-anchor" href="#c-phone-numbers" aria-label="Permalink to &quot;C. Phone Numbers&quot;">​</a></h3><p><strong>Ikteb in-numri ta’ dawn in-nies.</strong> Write these people&#39;s phone numbers.</p><ul><li><strong>ikteb</strong> write.</li><li><strong>in-numri</strong> the numbers / phone numbers.</li><li><strong>ta’</strong> of.</li><li><strong>dawn in-nies</strong> these people.</li><li><strong>is-Sur</strong> Mr.</li><li><strong>Vella</strong> a surname.</li></ul><p>Reference digit-by-digit reading for <strong>Is-Sur Vella — 21678723</strong>:</p><blockquote><p>tnejn, wieħed, sitta, sebgħa, tmienja, sebgħa, tnejn, tlieta</p></blockquote><ul><li><strong>tnejn</strong> 2.</li><li><strong>wieħed</strong> 1.</li><li><strong>sitta</strong> 6.</li><li><strong>sebgħa</strong> 7.</li><li><strong>tmienja</strong> 8.</li><li><strong>sebgħa</strong> 7.</li><li><strong>tnejn</strong> 2.</li><li><strong>tlieta</strong> 3.</li></ul><p>Reading a phone number digit by digit is a suitable way to read it here; don&#39;t read the whole eight-digit number as an integer of tens of millions.</p><hr><h2 id="_11-c-phone-numbers-continued" tabindex="-1">11 C. Phone Numbers (Continued) <a class="header-anchor" href="#_11-c-phone-numbers-continued" aria-label="Permalink to &quot;11 C. Phone Numbers (Continued)&quot;">​</a></h2><table><thead><tr><th>Original number</th><th>Digit-by-digit reference answer in words</th></tr></thead><tbody><tr><td>Is-Sur Dimech — 99871803</td><td><strong>disgħa</strong> 9<br><strong>disgħa</strong> 9<br><strong>tmienja</strong> 8<br><strong>sebgħa</strong> 7<br><strong>wieħed</strong> 1<br><strong>tmienja</strong> 8<br><strong>żero</strong> 0<br><strong>tlieta</strong> 3</td></tr><tr><td>Is-Sur Psaila — 27231234</td><td><strong>tnejn</strong> 2<br><strong>sebgħa</strong> 7<br><strong>tnejn</strong> 2<br><strong>tlieta</strong> 3<br><strong>wieħed</strong> 1<br><strong>tnejn</strong> 2<br><strong>tlieta</strong> 3<br><strong>erbgħa</strong> 4</td></tr><tr><td>Is-Sur Bonanno — 77002517</td><td><strong>sebgħa</strong> 7<br><strong>sebgħa</strong> 7<br><strong>żero</strong> 0<br><strong>żero</strong> 0<br><strong>tnejn</strong> 2<br><strong>ħamsa</strong> 5<br><strong>wieħed</strong> 1<br><strong>sebgħa</strong> 7</td></tr></tbody></table><p><strong>Dimech / Psaila / Bonanno</strong> are surnames; the title <code>Is-Sur</code> means Mr.</p><h3 id="d-sums" tabindex="-1">D. Sums <a class="header-anchor" href="#d-sums" aria-label="Permalink to &quot;D. Sums&quot;">​</a></h3><p><strong>Aħdem dawn is-somom u ikteb it-tweġiba fi kliem bil-Malti.</strong></p><p>Work out these sums and write the answer in words in Maltese.</p><ul><li><strong>aħdem</strong> do, work out.</li><li><strong>dawn</strong> these.</li><li><strong>is-somom</strong> the sums.</li><li><strong>u</strong> and.</li><li><strong>ikteb</strong> write.</li><li><strong>it-tweġiba</strong> the answer.</li><li><strong>fi kliem</strong> in words.</li><li><strong>bil-Malti</strong> in Maltese.</li></ul><table><thead><tr><th>Sum</th><th>Numeric answer</th><th>Answer in words and English</th></tr></thead><tbody><tr><td>1 + 5</td><td>6</td><td><strong>sitta</strong> six; given in the textbook</td></tr><tr><td>7 − 3</td><td>4</td><td><strong>erbgħa</strong> four</td></tr><tr><td>2 − 1</td><td>1</td><td><strong>wieħed</strong> one</td></tr><tr><td>3 × 3</td><td>9</td><td><strong>disgħa</strong> nine</td></tr><tr><td>9 + 1</td><td>10</td><td><strong>għaxra</strong> ten</td></tr><tr><td>4 − 2</td><td>2</td><td><strong>tnejn</strong> two</td></tr><tr><td>8 × 2</td><td>16</td><td><strong>sittax</strong> sixteen</td></tr><tr><td>10 × 2</td><td>20</td><td><strong>għoxrin</strong> twenty</td></tr><tr><td>9 + 4</td><td>13</td><td><strong>tlettax</strong> thirteen</td></tr><tr><td>10 + 7</td><td>17</td><td><strong>sbatax</strong> seventeen</td></tr><tr><td>20 − 1</td><td>19</td><td><strong>dsatax</strong> nineteen</td></tr><tr><td>7 × 2</td><td>14</td><td><strong>erbatax</strong> fourteen</td></tr></tbody></table><p>The answers are used independently, so <code>erbgħa</code> is written rather than the before-noun form <code>erba’</code>.</p><hr><h2 id="_12-compound-number-structure" tabindex="-1">12 Compound Number Structure <a class="header-anchor" href="#_12-compound-number-structure" aria-label="Permalink to &quot;12 Compound Number Structure&quot;">​</a></h2><p><strong>In-Numri mill-20 sal-100 — Kompli din it-tabella.</strong> The numbers from 20 to 100 — complete this table.</p><ul><li><strong>in-numri</strong> the numbers.</li><li><strong>mill-20</strong> from 20.</li><li><strong>sal-100</strong> to 100.</li><li><strong>kompli</strong> complete.</li><li><strong>din it-tabella</strong> this table.</li></ul><p>For non-tens numbers from 21 to 99, this page uses <strong>ones + u + tens</strong>:</p><ul><li><strong>wieħed</strong> one.</li><li><strong>u</strong> and.</li><li><strong>għoxrin</strong> twenty.</li><li><strong>wieħed u għoxrin</strong> 21.</li><li><strong>sebgħa u sittin</strong> 67, i.e. 7 + 60.</li><li><strong>tnejn u erbgħin</strong> 42, i.e. 2 + 40.</li></ul><h3 id="full-table-of-reference-answers" tabindex="-1">Full Table of Reference Answers <a class="header-anchor" href="#full-table-of-reference-answers" aria-label="Permalink to &quot;Full Table of Reference Answers&quot;">​</a></h3><table><thead><tr><th>Tens/hundreds</th><th>Middle column: answer and breakdown</th><th>Right column: answer and breakdown</th></tr></thead><tbody><tr><td><strong>għoxrin</strong> 20</td><td>21 = <strong>wieħed u għoxrin</strong><br><strong>wieħed</strong> 1<br><strong>u</strong> and<br><strong>għoxrin</strong> 20</td><td>25 = <strong>ħamsa u għoxrin</strong><br><strong>ħamsa</strong> 5<br><strong>u</strong> and<br><strong>għoxrin</strong> 20</td></tr><tr><td><strong>tletin</strong> 30</td><td>38 = <strong>tmienja u tletin</strong><br><strong>tmienja</strong> 8<br><strong>u</strong> and<br><strong>tletin</strong> 30</td><td>33 = <strong>tlieta u tletin</strong><br><strong>tlieta</strong> 3<br><strong>u</strong> and<br><strong>tletin</strong> 30</td></tr><tr><td><strong>erbgħin</strong> 40</td><td>42 = <strong>tnejn u erbgħin</strong><br><strong>tnejn</strong> 2<br><strong>u</strong> and<br><strong>erbgħin</strong> 40</td><td>46 = <strong>sitta u erbgħin</strong><br><strong>sitta</strong> 6<br><strong>u</strong> and<br><strong>erbgħin</strong> 40</td></tr><tr><td><strong>ħamsin</strong> 50</td><td>53 = <strong>tlieta u ħamsin</strong><br><strong>tlieta</strong> 3<br><strong>u</strong> and<br><strong>ħamsin</strong> 50</td><td>59 = <strong>disgħa u ħamsin</strong><br><strong>disgħa</strong> 9<br><strong>u</strong> and<br><strong>ħamsin</strong> 50</td></tr><tr><td><strong>sittin</strong> 60</td><td>64 = <strong>erbgħa u sittin</strong><br><strong>erbgħa</strong> 4<br><strong>u</strong> and<br><strong>sittin</strong> 60</td><td>67 = <strong>sebgħa u sittin</strong><br><strong>sebgħa</strong> 7<br><strong>u</strong> and<br><strong>sittin</strong> 60</td></tr><tr><td><strong>sebgħin</strong> 70</td><td>71 = <strong>wieħed u sebgħin</strong><br><strong>wieħed</strong> 1<br><strong>u</strong> and<br><strong>sebgħin</strong> 70</td><td>78 = <strong>tmienja u sebgħin</strong><br><strong>tmienja</strong> 8<br><strong>u</strong> and<br><strong>sebgħin</strong> 70</td></tr><tr><td><strong>tmenin</strong> 80</td><td>85 = <strong>ħamsa u tmenin</strong><br><strong>ħamsa</strong> 5<br><strong>u</strong> and<br><strong>tmenin</strong> 80</td><td>88 = <strong>tmienja u tmenin</strong><br><strong>tmienja</strong> 8<br><strong>u</strong> and<br><strong>tmenin</strong> 80</td></tr><tr><td><strong>disgħin</strong> 90</td><td>92 = <strong>tnejn u disgħin</strong><br><strong>tnejn</strong> 2<br><strong>u</strong> and<br><strong>disgħin</strong> 90</td><td>96 = <strong>sitta u disgħin</strong><br><strong>sitta</strong> 6<br><strong>u</strong> and<br><strong>disgħin</strong> 90</td></tr><tr><td><strong>mija</strong> 100</td><td>101 = <strong>mija u wieħed</strong><br><strong>mija</strong> 100<br><strong>u</strong> and<br><strong>wieħed</strong> 1</td><td>105 = <strong>mija u ħamsa</strong><br><strong>mija</strong> 100<br><strong>u</strong> and<br><strong>ħamsa</strong> 5</td></tr></tbody></table><p><strong>Note:</strong> the number <code>100</code> reads <code>mija</code> on its own; before a noun the common form is <code>mitt</code>, as in the next page&#39;s <code>mitt ewro</code>; don&#39;t carry <code>mija ewro</code> over.</p><hr><h2 id="_13-b-listening-options-how-to-read-each-number" tabindex="-1">13 B. Listening Options: How to Read Each Number <a class="header-anchor" href="#_13-b-listening-options-how-to-read-each-number" aria-label="Permalink to &quot;13 B. Listening Options: How to Read Each Number&quot;">​</a></h2><p><strong>Agħmel ċirku madwar in-numru li tisma’.</strong> Circle the number you hear.</p><ul><li><strong>agħmel</strong> make, draw.</li><li><strong>ċirku</strong> circle.</li><li><strong>madwar</strong> around.</li><li><strong>in-numru</strong> the number.</li><li><strong>li tisma’</strong> that you hear.</li></ul><table><thead><tr><th>No.</th><th>Left option</th><th>Right option</th></tr></thead><tbody><tr><td>1</td><td>13 — <strong>tlettax</strong> thirteen</td><td>33 — <strong>tlieta u tletin</strong> thirty-three</td></tr><tr><td>2</td><td>51 — <strong>wieħed u ħamsin</strong> fifty-one</td><td>59 — <strong>disgħa u ħamsin</strong> fifty-nine</td></tr><tr><td>3</td><td>60 — <strong>sittin</strong> sixty</td><td>65 — <strong>ħamsa u sittin</strong> sixty-five</td></tr><tr><td>4</td><td>82 — <strong>tnejn u tmenin</strong> eighty-two</td><td>28 — <strong>tmienja u għoxrin</strong> twenty-eight</td></tr><tr><td>5</td><td>75 — <strong>ħamsa u sebgħin</strong> seventy-five</td><td>57 — <strong>sebgħa u ħamsin</strong> fifty-seven</td></tr><tr><td>6</td><td>49 — <strong>disgħa u erbgħin</strong> forty-nine</td><td>94 — <strong>erbgħa u disgħin</strong> ninety-four</td></tr><tr><td>7</td><td>22 — <strong>tnejn u għoxrin</strong> twenty-two</td><td>23 — <strong>tlieta u għoxrin</strong> twenty-three</td></tr><tr><td>8</td><td>9 — <strong>disgħa</strong> nine</td><td>99 — <strong>disgħa u disgħin</strong> ninety-nine</td></tr><tr><td>9</td><td>67 — <strong>sebgħa u sittin</strong> sixty-seven</td><td>76 — <strong>sitta u sebgħin</strong> seventy-six</td></tr><tr><td>10</td><td>88 — <strong>tmienja u tmenin</strong> eighty-eight</td><td>82 — <strong>tnejn u tmenin</strong> eighty-two</td></tr></tbody></table><p>The <strong>u</strong> inside compound numbers means &quot;and&quot;; the values of the parts come from pages 11 and 13. <strong>No recording is available, so all options are kept and no correct option is assumed.</strong></p><h3 id="c-number-fill-in-full-sentences-and-word-by-word-breakdown" tabindex="-1">C. Number Fill-in: Full Sentences and Word-by-Word Breakdown <a class="header-anchor" href="#c-number-fill-in-full-sentences-and-word-by-word-breakdown" aria-label="Permalink to &quot;C. Number Fill-in: Full Sentences and Word-by-Word Breakdown&quot;">​</a></h3><p><strong>Imla l-vojt billi tikteb in-numri fi kliem — HW.</strong> Fill in the blanks by writing the numbers in words — homework.</p><ul><li><strong>imla l-vojt</strong> fill in the blank.</li><li><strong>billi tikteb</strong> by writing.</li><li><strong>in-numri</strong> the numbers.</li><li><strong>fi kliem</strong> in words.</li><li><strong>HW</strong> homework.</li></ul><table><thead><tr><th>Completed sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. In-nanna għandha tmenin sena u n-nannu għandu ħamsa u tmenin sena.</td><td>Grandma is 80 and grandpa is 85.<br><strong>in-nanna</strong> the grandmother<br><strong>għandha</strong> she has (age structure)<br><strong>tmenin</strong> 80<br><strong>sena</strong> years<br><strong>u</strong> and<br><strong>n-nannu</strong> the grandfather<br><strong>għandu</strong> he has<br><strong>ħamsa u tmenin</strong> 85<br><strong>sena</strong> years.</td></tr><tr><td>2. Xtrajt tnejn u ħamsin ktieb biex naqra wieħed kull ġimgħa.</td><td>I bought 52 books so that I could read one every week.<br><strong>xtrajt</strong> I bought<br><strong>tnejn u ħamsin</strong> 52<br><strong>ktieb</strong> book (singular in this counting structure)<br><strong>biex</strong> so that<br><strong>naqra</strong> I read<br><strong>wieħed</strong> one (referring to masculine ktieb)<br><strong>kull</strong> every<br><strong>ġimgħa</strong> week.</td></tr><tr><td>3. Għandi ħamsa u għoxrin libsa; wieħed u tletin xalla u ħamsa u ħamsin kowt.</td><td>I have 25 dresses, 31 shawls and 55 coats.<br><strong>għandi</strong> I have<br><strong>ħamsa u għoxrin</strong> 25<br><strong>libsa</strong> dress<br><strong>wieħed u tletin</strong> 31<br><strong>xalla</strong> shawl<br><strong>u</strong> and<br><strong>ħamsa u ħamsin</strong> 55<br><strong>kowt</strong> coat.</td></tr><tr><td>4. Infaqna sebgħa u sittin ewro biex irranġajna t-televixin.</td><td>We spent 67 euros to repair the TV.<br><strong>infaqna</strong> we spent<br><strong>sebgħa u sittin</strong> 67<br><strong>ewro</strong> euros<br><strong>biex</strong> to<br><strong>irranġajna</strong> we repaired (kept as the original past tense)<br><strong>t-televixin</strong> the TV.</td></tr><tr><td>5. Qlajt mitt ewro bħala rigal.</td><td>I received 100 euros as a gift.<br><strong>qlajt</strong> I got, received<br><strong>mitt</strong> one hundred (before a noun)<br><strong>ewro</strong> euros<br><strong>bħala</strong> as<br><strong>rigal</strong> gift.</td></tr><tr><td>6a. Ommi żżewġet ta’ tmienja u għoxrin sena.</td><td>My mother got married at 28.<br><strong>ommi</strong> my mother<br><strong>żżewġet</strong> she married<br><strong>ta’</strong> at (age)<br><strong>tmienja u għoxrin</strong> 28<br><strong>sena</strong> years.</td></tr><tr><td>6b. Meta kellha disgħa u għoxrin sena, welldet lil oħti u meta kellha tnejn u tletin sena welldet lili.</td><td>When she was 29 she gave birth to my sister, and when she was 32 she gave birth to me.<br><strong>meta</strong> when<br><strong>kellha</strong> she had (past, of age)<br><strong>disgħa u għoxrin</strong> 29<br><strong>sena</strong> years<br><strong>welldet</strong> she gave birth to<br><strong>lil oħti</strong> my sister (object)<br><strong>u</strong> and<br><strong>tnejn u tletin</strong> 32<br><strong>lili</strong> me (object).</td></tr><tr><td>7. Morna l-Akkwarju Nazzjonali u rajna tnejn u sebgħin speċi ta’ ħut differenti.</td><td>We went to the National Aquarium and saw 72 different species of fish.<br><strong>morna</strong> we went<br><strong>l-Akkwarju Nazzjonali</strong> the National Aquarium<br><strong>u</strong> and<br><strong>rajna</strong> we saw<br><strong>tnejn u sebgħin</strong> 72<br><strong>speċi</strong> species<br><strong>ta’ ħut</strong> of fish<br><strong>differenti</strong> different.</td></tr></tbody></table><p>The tense combination in item 4 (<code>biex irranġajna</code>) should not be mechanically copied into a new sentence; as a learning rewrite you could say <strong>Infaqna sebgħa u sittin ewro fuq it-tiswija tat-televixin.</strong> (We spent 67 euros on repairing the TV.)</p><ul><li><strong>fuq</strong> on, for.</li><li><strong>it-tiswija</strong> the repair.</li><li><strong>tat-televixin</strong> of the TV.</li></ul><hr><h2 id="_14-grammar-notes-line-by-line" tabindex="-1">14 Grammar Notes, Line by Line <a class="header-anchor" href="#_14-grammar-notes-line-by-line" aria-label="Permalink to &quot;14 Grammar Notes, Line by Line&quot;">​</a></h2><table><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>In-numri u n-nomi</td><td>Numbers and nouns.<br><strong>in-numri</strong> the numbers<br><strong>u</strong> and<br><strong>n-nomi</strong> the nouns.</td></tr><tr><td>In-nomi huma kliem li juru oġġetti, persuni, annimali u postijiet.</td><td>Nouns are words that show objects, people, animals and places.<br><strong>in-nomi</strong> the nouns<br><strong>huma</strong> are<br><strong>kliem</strong> words<br><strong>li</strong> that<br><strong>juru</strong> show<br><strong>oġġetti</strong> objects<br><strong>persuni</strong> people<br><strong>annimali</strong> animals<br><strong>u</strong> and<br><strong>postijiet</strong> places.</td></tr><tr><td>Meta n-numri jintużaw flimkien man-nomi, jistgħu jibdlu s-sura tagħhom.</td><td>When numbers are used together with nouns, the numbers may change their form.<br><strong>meta</strong> when<br><strong>n-numri</strong> the numbers<br><strong>jintużaw</strong> are used (plural)<br><strong>flimkien</strong> together<br><strong>man-nomi</strong> with nouns<br><strong>jistgħu</strong> they can<br><strong>jibdlu</strong> change<br><strong>s-sura</strong> the form<br><strong>tagħhom</strong> their.</td></tr></tbody></table><h3 id="_1-placed-after-the-noun-distinguishing-gender" tabindex="-1">1: Placed After the Noun, Distinguishing Gender <a class="header-anchor" href="#_1-placed-after-the-noun-distinguishing-gender" aria-label="Permalink to &quot;1: Placed After the Noun, Distinguishing Gender&quot;">​</a></h3><ul><li><strong>lapes wieħed</strong> one pencil.</li><li><strong>lapes</strong> pencil, masculine.</li><li><strong>wieħed</strong> one (masculine).</li><li><strong>karta waħda</strong> one sheet of paper.</li><li><strong>karta</strong> paper, feminine.</li><li><strong>waħda</strong> one (feminine).</li><li><strong>tifel wieħed</strong> one boy.</li><li><strong>tifla waħda</strong> one girl.</li><li><strong>m</strong> masculine.</li><li><strong>f</strong> feminine.</li></ul><h3 id="_2–10-numbers-shorten-and-take-a-plural-noun" tabindex="-1">2–10: Numbers Shorten and Take a Plural Noun <a class="header-anchor" href="#_2–10-numbers-shorten-and-take-a-plural-noun" aria-label="Permalink to &quot;2–10: Numbers Shorten and Take a Plural Noun&quot;">​</a></h3><table><thead><tr><th>Standalone number</th><th>Form before a noun</th><th>Ordinary plural example and breakdown</th><th>Vowel-initial example and breakdown</th></tr></thead><tbody><tr><td><strong>tnejn</strong> two</td><td><strong>żewġ / żewġt</strong></td><td><strong>żewġ lapsijiet</strong> two pencils<br><strong>żewġ</strong> two<br><strong>lapsijiet</strong> pencils (plural)</td><td><strong>żewġt itfal</strong> two children<br><strong>żewġt</strong> two, before itfal<br><strong>itfal</strong> children (plural)</td></tr><tr><td><strong>tlieta</strong> three</td><td><strong>tliet / tlitt</strong></td><td><strong>tliet karti</strong> three sheets of paper<br><strong>tliet</strong> three<br><strong>karti</strong> paper (plural)</td><td><strong>tlitt itfal</strong> three children<br><strong>tlitt</strong> three<br><strong>itfal</strong> children</td></tr><tr><td><strong>erbgħa</strong> four</td><td><strong>erba’ / erbat</strong></td><td><strong>erba’ lapsijiet</strong> four pencils<br><strong>erba’</strong> four<br><strong>lapsijiet</strong> pencils</td><td><strong>erbat itfal</strong> four children<br><strong>erbat</strong> four<br><strong>itfal</strong> children</td></tr><tr><td><strong>ħamsa</strong> five</td><td><strong>ħames / ħamest</strong></td><td><strong>ħames karti</strong> five sheets of paper<br><strong>ħames</strong> five<br><strong>karti</strong> paper</td><td><strong>ħamest itfal</strong> five children<br><strong>ħamest</strong> five<br><strong>itfal</strong> children</td></tr><tr><td><strong>sitta</strong> six</td><td><strong>sitt</strong></td><td><strong>sitt lapsijiet</strong> six pencils<br><strong>sitt</strong> six<br><strong>lapsijiet</strong> pencils</td><td><strong>sitt itfal</strong> six children<br><strong>sitt</strong> six<br><strong>itfal</strong> children</td></tr><tr><td><strong>sebgħa</strong> seven</td><td><strong>seba’ / sebat</strong></td><td><strong>seba’ karti</strong> seven sheets of paper<br><strong>seba’</strong> seven<br><strong>karti</strong> paper</td><td><strong>sebat itfal</strong> seven children<br><strong>sebat</strong> seven<br><strong>itfal</strong> children</td></tr><tr><td><strong>tmienja</strong> eight</td><td><strong>tmien / tmint</strong></td><td><strong>tmien lapsijiet</strong> eight pencils<br><strong>tmien</strong> eight<br><strong>lapsijiet</strong> pencils</td><td><strong>tmint itfal</strong> eight children<br><strong>tmint</strong> eight<br><strong>itfal</strong> children</td></tr><tr><td><strong>disgħa</strong> nine</td><td><strong>disa’ / disat</strong></td><td><strong>disa’ karti</strong> nine sheets of paper<br><strong>disa’</strong> nine<br><strong>karti</strong> paper</td><td><strong>disat itfal</strong> nine children<br><strong>disat</strong> nine<br><strong>itfal</strong> children</td></tr><tr><td><strong>għaxra</strong> ten</td><td><strong>għaxar / għaxart</strong></td><td><strong>għaxar lapsijiet</strong> ten pencils<br><strong>għaxar</strong> ten<br><strong>lapsijiet</strong> pencils</td><td><strong>għaxart itfal</strong> ten children<br><strong>għaxart</strong> ten<br><strong>itfal</strong> children</td></tr></tbody></table><p>The original table also lists <code>żewġ karti</code> through <code>għaxar karti</code>, and <code>tliet lapsijiet</code> through <code>disa’ lapsijiet</code>. The meanings and changes follow the same table; no different rule is invented.</p><p><strong>The -t forms here are used in vowel-initial environments like the itfal shown on this page; don&#39;t generalise them to all words just from the alphabet. The next page&#39;s ħwienet / iħwienet etc. also involves a preposed vowel on the noun.</strong></p><h3 id="_11–19-connecting-form-il-noun-in-the-singular" tabindex="-1">11–19: Connecting Form -il, Noun in the Singular <a class="header-anchor" href="#_11–19-connecting-form-il-noun-in-the-singular" aria-label="Permalink to &quot;11–19: Connecting Form -il, Noun in the Singular&quot;">​</a></h3><table><thead><tr><th>Number</th><th>Number + noun</th><th>Translation and breakdown</th></tr></thead><tbody><tr><td>11</td><td><strong>ħdax-il lapes</strong></td><td>eleven pencils.<br><strong>ħdax-il</strong> eleven (before a noun)<br><strong>lapes</strong> pencil (singular form)</td></tr><tr><td>12</td><td><strong>tnax-il karta</strong></td><td>twelve sheets of paper.<br><strong>tnax-il</strong> twelve<br><strong>karta</strong> paper (singular form)</td></tr><tr><td>13</td><td><strong>tlettax-il lapes</strong></td><td>thirteen pencils.<br><strong>tlettax-il</strong> thirteen<br><strong>lapes</strong> pencil</td></tr><tr><td>14</td><td><strong>erbatax-il karta</strong></td><td>fourteen sheets of paper.<br><strong>erbatax-il</strong> fourteen<br><strong>karta</strong> paper</td></tr><tr><td>15</td><td><strong>ħmistax-il lapes</strong></td><td>fifteen pencils.<br><strong>ħmistax-il</strong> fifteen<br><strong>lapes</strong> pencil</td></tr><tr><td>16</td><td><strong>sittax-il karta</strong></td><td>sixteen sheets of paper.<br><strong>sittax-il</strong> sixteen<br><strong>karta</strong> paper</td></tr><tr><td>17</td><td><strong>sbatax-il lapes</strong></td><td>seventeen pencils.<br><strong>sbatax-il</strong> seventeen<br><strong>lapes</strong> pencil</td></tr><tr><td>18</td><td><strong>tmintax-il karta</strong></td><td>eighteen sheets of paper.<br><strong>tmintax-il</strong> eighteen<br><strong>karta</strong> paper</td></tr><tr><td>19</td><td><strong>dsatax-il lapes</strong></td><td>nineteen pencils.<br><strong>dsatax-il</strong> nineteen<br><strong>lapes</strong> pencil</td></tr><tr><td>20</td><td><strong>għoxrin karta</strong></td><td>twenty sheets of paper; no extra -il.<br><strong>għoxrin</strong> twenty<br><strong>karta</strong> paper (singular form)</td></tr></tbody></table><p>The textbook lists <code>lapes</code>, <code>karta</code> and <code>tifel u tifla</code> in three columns for each row; change the number to the matching row form and the original full forms are in the transcript.</p><ul><li><strong>tifel</strong> boy (singular).</li><li><strong>u</strong> and.</li><li><strong>tifla</strong> girl (singular).</li><li><strong>ħdax-il tifel u tifla</strong> is used in the textbook to demonstrate counting eleven boys/girls; it cannot be treated as a maths formula for how many of each gender.</li></ul><h2 id="key-contrast-tliet-bajdiet-three-eggs-but-tnax-il-gallettina-twelve-biscuits-a-number-before-a-noun-does-not-always-take-a-plural" tabindex="-1"><strong>Key contrast:</strong> <code>tliet bajdiet</code> three eggs, but <code>tnax-il gallettina</code> twelve biscuits; a number before a noun does not always take a plural. <a class="header-anchor" href="#key-contrast-tliet-bajdiet-three-eggs-but-tnax-il-gallettina-twelve-biscuits-a-number-before-a-noun-does-not-always-take-a-plural" aria-label="Permalink to &quot;**Key contrast:** `tliet bajdiet` three eggs, but `tnax-il gallettina` twelve biscuits; a number before a noun does not always take a plural.&quot;">​</a></h2><h2 id="_15-understanding-the-exercise-word-by-word" tabindex="-1">15 Understanding the Exercise, Word by Word <a class="header-anchor" href="#_15-understanding-the-exercise-word-by-word" aria-label="Permalink to &quot;15 Understanding the Exercise, Word by Word&quot;">​</a></h2><p><strong>Imla l-vojt bin-numru t-tajjeb skont dak li hemm fil-parentesi u aqta’ linja taħt in-nom li jixraq.</strong></p><p>Fill in the blank with the correct number according to what is in the brackets, and draw a line under the noun that fits.</p><ul><li><strong>imla l-vojt</strong> fill in the blank.</li><li><strong>bin-numru t-tajjeb</strong> with the correct number.</li><li><strong>skont</strong> according to.</li><li><strong>dak li hemm</strong> what there is.</li><li><strong>fil-parentesi</strong> in the brackets.</li><li><strong>u</strong> and.</li><li><strong>aqta’ linja</strong> draw a line (whole expression).</li><li><strong>taħt</strong> under.</li><li><strong>in-nom</strong> the noun.</li><li><strong>li jixraq</strong> that fits.</li></ul><p>Example: <strong>Xtrajt tliet lanġasiet.</strong> I bought three pears.</p><ul><li><strong>xtrajt</strong> I bought.</li><li><strong>tliet</strong> three.</li><li><strong>lanġasiet</strong> pears (countable plural).</li></ul><h3 id="all-reference-answers" tabindex="-1">All Reference Answers <a class="header-anchor" href="#all-reference-answers" aria-label="Permalink to &quot;All Reference Answers&quot;">​</a></h3><p>The following sentences keep the correct option directly; the forms to be crossed out are omitted.</p><table><thead><tr><th>Completed sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Jien għandi għoxrin sena.</td><td>I am twenty years old.<br><strong>jien</strong> I<br><strong>għandi</strong> I have<br><strong>għoxrin</strong> twenty<br><strong>sena</strong> years (singular form here; not snin).</td></tr><tr><td>2. Fit-tiġrija konna ħdax-il tifel u tifla.</td><td>In the race we were eleven boys and girls, as in the textbook.<br><strong>fit-tiġrija</strong> in the race<br><strong>konna</strong> we were<br><strong>ħdax-il</strong> eleven (before a noun)<br><strong>tifel u tifla</strong> boy and girl; the original chooses this group, not tfal.</td></tr><tr><td>3. Oħti ż-żgħira għandha ħames snin.</td><td>My little sister is five years old.<br><strong>oħti</strong> my sister<br><strong>ż-żgħira</strong> the little one<br><strong>għandha</strong> she has<br><strong>ħames</strong> five (before a noun)<br><strong>snin</strong> years (plural).</td></tr><tr><td>4. Kilt tuffieħa waħda u żewġ larinġiet.</td><td>I ate one apple and two oranges.<br><strong>kilt</strong> I ate<br><strong>tuffieħa</strong> an apple (feminine)<br><strong>waħda</strong> one (feminine, after the noun)<br><strong>u</strong> and<br><strong>żewġ</strong> two<br><strong>larinġiet</strong> oranges (countable plural), not the collective larinġ.</td></tr><tr><td>5. Morna nduru għaxart iħwienet u xtrajna erbat ilbiesi.</td><td>We went around ten shops and bought four dresses.<br><strong>morna</strong> we went<br><strong>nduru</strong> we go around<br><strong>għaxart</strong> ten (-t form here)<br><strong>iħwienet</strong> shops (plural, with preposed i)<br><strong>u</strong> and<br><strong>xtrajna</strong> we bought<br><strong>erbat</strong> four (before a vowel)<br><strong>ilbiesi</strong> dresses (plural; the initial il- is part of the word form, not an article added by the exercise).</td></tr><tr><td>6. Id-dar għandna tliet għasafar u tlitt iklieb.</td><td>At home we have three birds and three dogs.<br><strong>id-dar</strong> at home<br><strong>għandna</strong> we have<br><strong>tliet</strong> three<br><strong>għasafar</strong> birds (plural)<br><strong>u</strong> and<br><strong>tlitt</strong> three (before a preposed vowel here)<br><strong>iklieb</strong> dogs (klieb with the preposed i form).</td></tr><tr><td>7. Kien hemm ħmistax-il persuna fil-kju.</td><td>There were fifteen people in the queue.<br><strong>kien hemm</strong> there were<br><strong>ħmistax-il</strong> fifteen<br><strong>persuna</strong> person (singular form here)<br><strong>fil-kju</strong> in the queue.</td></tr><tr><td>8. Ilni noqgħod hawn Malta għal dawn l-aħħar seba’ snin.</td><td>I have been living here in Malta for the past seven years.<br><strong>ilni</strong> I have been... for<br><strong>noqgħod</strong> I live<br><strong>hawn</strong> here<br><strong>Malta</strong> Malta<br><strong>għal</strong> for<br><strong>dawn l-aħħar</strong> these last<br><strong>seba’</strong> seven (before a noun)<br><strong>snin</strong> years (plural).</td></tr><tr><td>9. F’Ġunju rrid nagħmel tmien eżamijiet.</td><td>In June I have to take eight exams.<br><strong>f’Ġunju</strong> in June<br><strong>rrid</strong> I must<br><strong>nagħmel</strong> I do, take<br><strong>tmien</strong> eight (before a noun)<br><strong>eżamijiet</strong> exams (plural).</td></tr><tr><td>10. Jien għandi disa’ kuġini. Erbgħa minnhom huma ikbar minni.</td><td>I have nine cousins; four of them are older than me.<br><strong>jien</strong> I<br><strong>għandi</strong> I have<br><strong>disa’</strong> nine (before a noun)<br><strong>kuġini</strong> cousins (plural)<br><strong>erbgħa</strong> four (standalone, referring to people)<br><strong>minnhom</strong> of them<br><strong>huma</strong> are<br><strong>ikbar</strong> bigger, older<br><strong>minni</strong> than me.</td></tr></tbody></table><p>Items 5 and 6 test exactly the <code>iħwienet / ilbiesi / iklieb</code> forms when joined to numbers; the i should not be removed to match an isolated dictionary headword.</p><hr><h2 id="_16-whether-the-number-directly-modifies-the-noun" tabindex="-1">16 Whether the Number Directly Modifies the Noun <a class="header-anchor" href="#_16-whether-the-number-directly-modifies-the-noun" aria-label="Permalink to &quot;16 Whether the Number Directly Modifies the Noun&quot;">​</a></h2><p><strong>X’inhi d-differenza bejn dawn?</strong> What is the difference between these?</p><ul><li><strong>x’inhi</strong> what is (feminine).</li><li><strong>d-differenza</strong> the difference.</li><li><strong>bejn</strong> between.</li><li><strong>dawn</strong> these.</li></ul><table><thead><tr><th>Standalone form</th><th>Before-noun form</th><th>Difference</th></tr></thead><tbody><tr><td><strong>erbgħa</strong> four</td><td><strong>erba’</strong> four…</td><td>standalone reading/referring to four, vs directly modifying a noun</td></tr><tr><td><strong>sebgħa</strong> seven</td><td><strong>seba’</strong> seven…</td><td>same</td></tr><tr><td><strong>disgħa</strong> nine</td><td><strong>disa’</strong> nine…</td><td>same</td></tr><tr><td><strong>ħamsa</strong> five</td><td><strong>ħames</strong> five…</td><td>the textbook uses this more obvious pair to help judge</td></tr></tbody></table><h3 id="explanations-and-example-sentences-line-by-line" tabindex="-1">Explanations and Example Sentences, Line by Line <a class="header-anchor" href="#explanations-and-example-sentences-line-by-line" aria-label="Permalink to &quot;Explanations and Example Sentences, Line by Line&quot;">​</a></h3><table><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Ħares ftit lejn l-aħħar sentenza tal-eżerċizzju li għadda u qabbilha ma’ ta’ taħtha.</td><td>Look briefly at the last sentence of the previous exercise and compare it with the one below it.<br><strong>ħares lejn</strong> look at<br><strong>ftit</strong> briefly<br><strong>l-aħħar sentenza</strong> the last sentence<br><strong>tal-eżerċizzju</strong> of the exercise<br><strong>li għadda</strong> that just passed, previous<br><strong>u</strong> and<br><strong>qabbilha</strong> compare it (-ha refers to sentenza)<br><strong>ma’</strong> with<br><strong>ta’ taħtha</strong> the one below it.</td></tr><tr><td>Jien għandi disa’ kuġini. Erbgħa minnhom huma ikbar minni.</td><td>I have nine cousins; four of them are older than me.<br><strong>jien għandi</strong> I have<br><strong>disa’</strong> nine (directly modifying the noun)<br><strong>kuġini</strong> cousins<br><strong>erbgħa</strong> four (no counted noun directly after it)<br><strong>minnhom</strong> of them<br><strong>huma</strong> are<br><strong>ikbar</strong> older<br><strong>minni</strong> than me.</td></tr><tr><td>Jien għandi ħames kuġini. Ħamsa minnhom huma ikbar minni.</td><td>I have five cousins; five of them are older than me.<br><strong>jien għandi</strong> I have<br><strong>ħames</strong> five (before the noun)<br><strong>kuġini</strong> cousins<br><strong>ħamsa</strong> five (standalone)<br><strong>minnhom</strong> of them<br><strong>huma ikbar minni</strong> are older than me.</td></tr><tr><td>X’qed tinnota? Uża n-numru ħamsa (5) bħala l-mudell ta’ kif trid tikteb in-numri erbgħa (4), sebgħa (7) u disgħa (9).</td><td>What do you notice? Use the number five (5) as the model for how you should write the numbers four (4), seven (7) and nine (9).<br><strong>x’qed tinnota</strong> what do you notice<br><strong>uża</strong> use<br><strong>n-numru</strong> the number<br><strong>ħamsa</strong> five<br><strong>bħala</strong> as<br><strong>l-mudell</strong> the model<br><strong>ta’ kif</strong> of how<br><strong>trid tikteb</strong> you should write<br><strong>in-numri</strong> the numbers<br><strong>erbgħa</strong> four<br><strong>sebgħa</strong> seven<br><strong>u</strong> and<br><strong>disgħa</strong> nine.</td></tr></tbody></table><p>Answer you could give: <strong>In-numru jinbidel meta jiġi qabel nom.</strong> The number changes when it comes before a noun.</p><ul><li><strong>in-numru</strong> the number.</li><li><strong>jinbidel</strong> changes.</li><li><strong>meta</strong> when.</li><li><strong>jiġi</strong> it comes, it appears.</li><li><strong>qabel</strong> before.</li><li><strong>nom</strong> noun.</li></ul><h3 id="b-all-fill-in-reference-answers" tabindex="-1">B. All Fill-in Reference Answers <a class="header-anchor" href="#b-all-fill-in-reference-answers" aria-label="Permalink to &quot;B. All Fill-in Reference Answers&quot;">​</a></h3><p><strong>Ikteb in-numru t-tajjeb.</strong> Write the correct number form.</p><ul><li><strong>ikteb</strong> write.</li><li><strong>in-numru</strong> the number.</li><li><strong>t-tajjeb</strong> the correct.</li></ul><table><thead><tr><th>Completed sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Xtrajt seba’ kotba, erbgħa minnhom huma bil-Malti.</td><td>I bought seven books; four of them are in Maltese.<br><strong>xtrajt</strong> I bought<br><strong>seba’</strong> seven (before a noun)<br><strong>kotba</strong> books (plural)<br><strong>erbgħa</strong> four (standalone, referring to the books)<br><strong>minnhom</strong> of them<br><strong>huma</strong> are<br><strong>bil-Malti</strong> in Maltese.</td></tr><tr><td>2. Kemm kontu nies ilbieraħ? Ilbieraħ konna disgħa.</td><td>How many of you were there yesterday? Yesterday there were nine of us.<br><strong>kemm</strong> how many<br><strong>kontu</strong> you were<br><strong>nies</strong> people<br><strong>ilbieraħ</strong> yesterday<br><strong>konna</strong> we were<br><strong>disgħa</strong> nine (standalone).</td></tr><tr><td>3. Martha hi erba’ snin ikbar minni.</td><td>Martha is four years older than me.<br><strong>Martha</strong> a name<br><strong>hi</strong> she is<br><strong>erba’</strong> four (before a noun)<br><strong>snin</strong> years<br><strong>ikbar</strong> older<br><strong>minni</strong> than me.</td></tr><tr><td>4. Xtaqt nixtri disa’ pitazzi imma tal-ħanut kellu biss sebgħa.</td><td>I wanted to buy nine notebooks, but the shopkeeper only had seven.<br><strong>xtaqt</strong> I wanted (past)<br><strong>nixtri</strong> I buy<br><strong>disa’</strong> nine (before a noun)<br><strong>pitazzi</strong> notebooks (plural)<br><strong>imma</strong> but<br><strong>tal-ħanut</strong> the shopkeeper<br><strong>kellu</strong> he had (past)<br><strong>biss</strong> only<br><strong>sebgħa</strong> seven (standalone, referring to the notebooks).</td></tr><tr><td>5. Is-sena l-oħra żort seba’ pajjiżi, erbgħa minnhom huma fl-Ewropa.</td><td>Last year I visited seven countries; four of them are in Europe.<br><strong>is-sena l-oħra</strong> last year<br><strong>żort</strong> I visited<br><strong>seba’</strong> seven (before a noun)<br><strong>pajjiżi</strong> countries (plural)<br><strong>erbgħa</strong> four (standalone)<br><strong>minnhom</strong> of them<br><strong>huma</strong> are, lie<br><strong>fl-Ewropa</strong> in Europe.</td></tr></tbody></table><hr><h2 id="_17-the-dual-line-by-line" tabindex="-1">17 The Dual, Line by Line <a class="header-anchor" href="#_17-the-dual-line-by-line" aria-label="Permalink to &quot;17 The Dual, Line by Line&quot;">​</a></h2><table><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Iktar numri... L-Għadd Imtenni</td><td>More numbers... the dual.<br><strong>iktar</strong> more<br><strong>numri</strong> numbers<br><strong>l-għadd</strong> the count, grammatical number<br><strong>imtenni</strong> dual, doubled.</td></tr><tr><td>Dan jintuża meta jkollna tnejn (2) minn xi nom.</td><td>This is used when we have two (2) of some noun.<br><strong>dan</strong> this<br><strong>jintuża</strong> is used<br><strong>meta</strong> when<br><strong>jkollna</strong> we have<br><strong>tnejn</strong> two<br><strong>minn</strong> of<br><strong>xi nom</strong> some noun.</td></tr><tr><td>Dan jispiċċa bl-ittri -ejn jew -ajn.</td><td>This form ends with the letters -ejn or -ajn.<br><strong>dan</strong> this form<br><strong>jispiċċa</strong> ends<br><strong>bl-ittri</strong> with the letters<br><strong>-ejn</strong> one dual ending<br><strong>jew</strong> or<br><strong>-ajn</strong> one dual ending.</td></tr><tr><td>Agħti l-għadd imtenni ta’ dawn in-nomi.</td><td>Give the dual of these nouns.<br><strong>agħti</strong> give<br><strong>l-għadd imtenni</strong> the dual<br><strong>ta’</strong> of<br><strong>dawn in-nomi</strong> these nouns.</td></tr></tbody></table><p>The dual cannot be formed mechanically by adding <code>-ejn</code> to every noun; there are stem changes and fixed forms. For example <code>sena → sentejn</code>, not adding to sena as it is.</p><h3 id="a-reference-answers-for-the-16-items" tabindex="-1">A. Reference Answers for the 16 Items <a class="header-anchor" href="#a-reference-answers-for-the-16-items" aria-label="Permalink to &quot;A. Reference Answers for the 16 Items&quot;">​</a></h3><table><thead><tr><th>No.</th><th>Singular → Dual</th><th>English and form notes</th></tr></thead><tbody><tr><td>1</td><td><strong>jum → jumejn</strong></td><td>one day → two days; already given in the original.</td></tr><tr><td>2</td><td><strong>id → idejn</strong></td><td>one hand → two hands.</td></tr><tr><td>3</td><td><strong>ħadd → ħaddejn</strong></td><td>one cheek → two cheeks; distinguish from Ħadd &quot;Sunday&quot; and the pronoun ħadd &quot;anyone/nobody&quot;.</td></tr><tr><td>4</td><td><strong>elf → elfejn</strong></td><td>one thousand → two thousand.</td></tr><tr><td>5</td><td><strong>għajn → għajnejn</strong></td><td>one eye → two eyes.</td></tr><tr><td>6</td><td><strong>sieq → saqajn</strong></td><td>one foot/leg → two feet/legs.</td></tr><tr><td>7</td><td><strong>driegħ → dirgħajn</strong></td><td>one arm → two arms.</td></tr><tr><td>8</td><td><strong>pass → passejn</strong></td><td>one step → two steps.</td></tr><tr><td>9</td><td><strong>spalla → spallejn</strong></td><td>one shoulder → two shoulders.</td></tr><tr><td>10</td><td><strong>rkoppa → rkopptejn</strong></td><td>one knee → two knees.</td></tr><tr><td>11</td><td><strong>siegħa → sagħtejn</strong></td><td>one hour → two hours.</td></tr><tr><td>12</td><td><strong>darba → darbtejn</strong></td><td>once → twice.</td></tr><tr><td>13</td><td><strong>ġimgħa → ġimagħtejn</strong></td><td>one week → two weeks.</td></tr><tr><td>14</td><td><strong>wiżna → wiżintejn</strong></td><td>one old weight unit wiżna → two units; the stem inserts i, not wiżntejn.</td></tr><tr><td>15</td><td><strong>sena → sentejn</strong></td><td>one year → two years.</td></tr><tr><td>16</td><td><strong>kelma → kelmtejn</strong></td><td>one word → two words; also used in idioms like &quot;a few words&quot;, by context.</td></tr></tbody></table><h3 id="b-completed-sentences-and-word-by-word-breakdown" tabindex="-1">B. Completed Sentences and Word-by-Word Breakdown <a class="header-anchor" href="#b-completed-sentences-and-word-by-word-breakdown" aria-label="Permalink to &quot;B. Completed Sentences and Word-by-Word Breakdown&quot;">​</a></h3><p><strong>Poġġi l-kliem li jinsab fil-parentesi, fl-għadd imtenni.</strong> Put the words in the brackets into the dual.</p><ul><li><strong>poġġi</strong> put, write.</li><li><strong>l-kliem</strong> the words.</li><li><strong>li jinsab</strong> that there are.</li><li><strong>fil-parentesi</strong> in the brackets.</li><li><strong>fl-għadd imtenni</strong> into the dual.</li></ul><table><thead><tr><th>Completed sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Kellu ħsieb li joqgħod ġimagħtejn Londra u minflok qagħad xahrejn.</td><td>He planned to stay in London for two weeks, but instead he stayed two months.<br><strong>kellu ħsieb</strong> he planned<br><strong>li</strong> that<br><strong>joqgħod</strong> he stays, lives<br><strong>ġimagħtejn</strong> two weeks<br><strong>Londra</strong> London<br><strong>u</strong> but<br><strong>minflok</strong> instead<br><strong>qagħad</strong> he stayed<br><strong>xahrejn</strong> two months (dual of xahar).</td></tr><tr><td>2. Ix-xofftejn, il-widnejn u l-għajnejn huma partijiet sensittivi tal-wiċċ.</td><td>The lips, ears and eyes are sensitive parts of the face.<br><strong>ix-xofftejn</strong> the two lips (xoffa → xofftejn)<br><strong>il-widnejn</strong> the two ears (widna → widnejn)<br><strong>u</strong> and<br><strong>l-għajnejn</strong> the two eyes<br><strong>huma</strong> are<br><strong>partijiet</strong> parts<br><strong>sensittivi</strong> sensitive (plural)<br><strong>tal-wiċċ</strong> of the face.</td></tr><tr><td>3. Kien hemm mal-mitejn ruħ fil-gallariji u mal-elfejn ruħ fit-toroq jistennew il-wasla tal-President.</td><td>There were about two hundred people on the balconies and about two thousand people in the streets waiting for the President&#39;s arrival.<br><strong>kien hemm</strong> there were<br><strong>mal-mitejn</strong> about two hundred (mitt → mitejn; with the article rewritten as a whole word)<br><strong>ruħ</strong> people (head-count unit)<br><strong>fil-gallariji</strong> on the balconies (plural)<br><strong>u</strong> and<br><strong>mal-elfejn</strong> about two thousand<br><strong>fit-toroq</strong> in the streets<br><strong>jistennew</strong> they wait<br><strong>il-wasla</strong> the arrival<br><strong>tal-President</strong> of the President.</td></tr><tr><td>4. Ommi xtrat ratlejn basal u wiżintejn patata.</td><td>My mother bought two ratal of onions and two wiżna of potatoes.<br><strong>ommi</strong> my mother<br><strong>xtrat</strong> she bought<br><strong>ratlejn</strong> the dual of ratal (two old weight units)<br><strong>basal</strong> onions<br><strong>u</strong> and<br><strong>wiżintejn</strong> the dual of wiżna<br><strong>patata</strong> potatoes.</td></tr><tr><td>5. Sentejn ilu sifirna darbtejn.</td><td>Two years ago we travelled abroad twice.<br><strong>sentejn</strong> two years<br><strong>ilu</strong> ago<br><strong>sifirna</strong> we went abroad<br><strong>darbtejn</strong> twice.</td></tr><tr><td>6. Il-ħajjata ħaditlu l-qies tal-ispallejn u t-tul tal-idejn biex tħitlu ġakketta.</td><td>The seamstress took his shoulder measurements and arm lengths in order to sew him a jacket.<br><strong>il-ħajjata</strong> the seamstress<br><strong>ħaditlu</strong> she took from him<br><strong>l-qies</strong> the measurements<br><strong>tal-ispallejn</strong> of the two shoulders (per the original ispalla form)<br><strong>u</strong> and<br><strong>t-tul</strong> the length<br><strong>tal-idejn</strong> of the hands/arms; here per the original id in the dual<br><strong>biex</strong> to<br><strong>tħitlu</strong> she sews for him<br><strong>ġakketta</strong> jacket.</td></tr></tbody></table><p>Item 6 answers with <code>id</code> as in the textbook; for a precise &quot;arm length&quot; one could describe it with <code>dirgħajn</code>, but that would be a wording change, not the dual of the bracketed word.</p><p>Form cross-check sources: <a href="https://en.wiktionary.org/wiki/%C4%A7add" target="_blank" rel="noreferrer">ħadd</a>, <a href="https://en.wiktionary.org/wiki/ratal" target="_blank" rel="noreferrer">ratal</a>, <a href="https://en.wiktionary.org/wiki/wi%C5%BCna" target="_blank" rel="noreferrer">wiżna</a>. Only the word meaning and inflected forms are checked against the entries; dictionary examples are not treated as textbook text.</p><hr><h2 id="_18-quantity-expressions-and-original-examples" tabindex="-1">18 Quantity Expressions and Original Examples <a class="header-anchor" href="#_18-quantity-expressions-and-original-examples" aria-label="Permalink to &quot;18 Quantity Expressions and Original Examples&quot;">​</a></h2><p><strong>L-Avverbji tal-Kwantità – Kemm?</strong> Quantity adverbs — how much?</p><ul><li><strong>l-avverbji</strong> the adverbs.</li><li><strong>tal-kwantità</strong> of quantity.</li><li><strong>kemm</strong> how much, how.</li></ul><p>The textbook groups these words under &quot;quantity adverbs&quot;; in practice some also act as pronouns or quantity determiners, so judge by their role in the sentence.</p><table><thead><tr><th>Word and original example</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Bilkemm — Bilkemm ilħaqt poġġejt bilqiegħda llum!</td><td>Hardly — I hardly managed to sit down today!<br><strong>bilkemm</strong> hardly, barely<br><strong>ilħaqt</strong> I managed<br><strong>poġġejt</strong> I sat<br><strong>bilqiegħda</strong> seated<br><strong>llum</strong> today.</td></tr><tr><td>Biss — Agħtini erbgħa biss, mhux iktar.</td><td>Only — Give me just four, no more.<br><strong>biss</strong> only<br><strong>agħtini</strong> give me<br><strong>erbgħa</strong> four (standalone)<br><strong>mhux</strong> not<br><strong>iktar</strong> more.</td></tr><tr><td>Biżżejjed — Daqshekk biżżejjed!</td><td>Enough — That&#39;s enough!<br><strong>biżżejjed</strong> enough<br><strong>daqshekk</strong> this much, to this extent.</td></tr><tr><td>Ftit / naqra — Jien niekol ftit.</td><td>A little — I eat little.<br><strong>ftit</strong> a little, a small amount<br><strong>naqra</strong> a bit (a quantity expression on this page, not the verb &quot;I read&quot;)<br><strong>jien</strong> I<br><strong>niekol</strong> I eat.</td></tr><tr><td>Ftit li xejn — Lil Toni rajtu ftit li xejn.</td><td>Very little, hardly at all — I hardly saw Toni at all.<br><strong>ftit li xejn</strong> very little, hardly (fixed phrase)<br><strong>lil Toni</strong> Toni (preposed object)<br><strong>rajtu</strong> I saw him (rajt + object -u).</td></tr><tr><td>Ħafna — Tina tħobb tgħum ħafna!</td><td>A lot/very — Tina loves swimming a lot! Also understandable as &quot;swims often&quot; by context.<br><strong>ħafna</strong> a lot, very<br><strong>Tina</strong> a name<br><strong>tħobb</strong> she likes<br><strong>tgħum</strong> she swims.</td></tr><tr><td>Iktar / iżjed — It-tarbija riedet iktar ħalib.</td><td>More — The baby wanted more milk.<br><strong>iktar / iżjed</strong> more<br><strong>it-tarbija</strong> the baby<br><strong>riedet</strong> she/it wanted (feminine)<br><strong>ħalib</strong> milk.</td></tr><tr><td>Inqas — Għandi inqas flus minnek.</td><td>Less — I have less money than you.<br><strong>inqas</strong> less<br><strong>għandi</strong> I have<br><strong>flus</strong> money<br><strong>minnek</strong> than you.</td></tr><tr><td>Kollox — Għidli kollox!</td><td>Everything — Tell me everything!<br><strong>kollox</strong> everything<br><strong>għidli</strong> tell me.</td></tr><tr><td>Żejjed — Baqa’ ż-żejjed u rfajtu għal għada.</td><td>Left over — There was some left over and I put it away for tomorrow.<br><strong>żejjed</strong> extra, left over<br><strong>baqa’</strong> there remained<br><strong>ż-żejjed</strong> the remainder (nominalised)<br><strong>u</strong> and<br><strong>rfajtu</strong> I put it away (rfajt + -u)<br><strong>għal għada</strong> for tomorrow.</td></tr></tbody></table><h3 id="fill-in-reference-answers-for-the-eight-items" tabindex="-1">Fill-in Reference Answers for the Eight Items <a class="header-anchor" href="#fill-in-reference-answers-for-the-eight-items" aria-label="Permalink to &quot;Fill-in Reference Answers for the Eight Items&quot;">​</a></h3><p><strong>Imla l-vojt bl-avverbji tal-kwantità.</strong> Fill in the blanks with the quantity adverbs.</p><ul><li><strong>imla l-vojt</strong> fill in the blank.</li><li><strong>bl-avverbji</strong> with the adverbs.</li><li><strong>tal-kwantità</strong> of quantity.</li></ul><p>The following are grammatically and contextually smooth reference answers; words may be repeated, as the original does not state &quot;use each word once&quot;.</p><table><thead><tr><th>Completed sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Il-lejl li għadda, bilkemm irqadt.</td><td>Last night I hardly slept.<br><strong>il-lejl</strong> the night<br><strong>li għadda</strong> that passed<br><strong>bilkemm</strong> hardly<br><strong>irqadt</strong> I slept.</td></tr><tr><td>2. Illum inħossni ħafna aħjar.</td><td>Today I feel much better.<br><strong>illum</strong> today<br><strong>inħossni</strong> I feel myself<br><strong>ħafna</strong> a lot (intensifying the comparison)<br><strong>aħjar</strong> better.</td></tr><tr><td>3. Jien għandi ftit ħbieb.</td><td>I have a few friends / not many friends.<br><strong>jien</strong> I<br><strong>għandi</strong> I have<br><strong>ftit</strong> a few<br><strong>ħbieb</strong> friends (plural).</td></tr><tr><td>4. Nixtieq li niltaqgħu iżjed drabi.</td><td>I&#39;d like us to meet more often.<br><strong>nixtieq</strong> I&#39;d like<br><strong>li</strong> that<br><strong>niltaqgħu</strong> we meet<br><strong>iżjed</strong> more<br><strong>drabi</strong> times.</td></tr><tr><td>5. Ilbieraħ ħadna ħafna gost!</td><td>Yesterday we had a lot of fun!<br><strong>ilbieraħ</strong> yesterday<br><strong>ħadna</strong> we had<br><strong>ħafna</strong> a lot<br><strong>gost</strong> fun; ħadna gost is &quot;we had fun&quot;.</td></tr><tr><td>6. Kollox kien tajjeb u tgħidx kemm kilna!</td><td>Everything was fine, and we ate an awful lot!<br><strong>kollox</strong> everything<br><strong>kien</strong> was<br><strong>tajjeb</strong> good<br><strong>u</strong> and<br><strong>tgħidx</strong> don&#39;t say (negative imperative)<br><strong>kemm</strong> how much<br><strong>kilna</strong> we ate; tgħidx kemm is exclamatory, &quot;you wouldn&#39;t believe how much&quot;.</td></tr><tr><td>7. Ma kien fadal xejn iżjed.</td><td>There was nothing left any more.<br><strong>ma</strong> negative marker<br><strong>kien fadal</strong> there was still left<br><strong>xejn</strong> nothing; echoes ma<br><strong>iżjed</strong> any more.</td></tr><tr><td>8. Xrobna ftit inbid aħmar.</td><td>We drank a little red wine.<br><strong>xrobna</strong> we drank<br><strong>ftit</strong> a little<br><strong>inbid</strong> wine<br><strong>aħmar</strong> red.</td></tr></tbody></table><p>Item 7 could also be <strong>Ma kien fadal xejn żejjed.</strong> (Nothing extra was left.)</p><ul><li><strong>żejjed</strong> extra.</li></ul><h2 id="key-review-points" tabindex="-1">Key Review Points <a class="header-anchor" href="#key-review-points" aria-label="Permalink to &quot;Key Review Points&quot;">​</a></h2><ol><li>Shopping politeness phrases: <strong>agħtini</strong> (give me), <strong>jekk jogħġbok</strong> (please), <strong>x’għandi nagħtik?</strong> (how much should I pay you?), <strong>bqija</strong> (change).</li><li>Ingredient expressions: <strong>gramma</strong> (gram), <strong>millilitru</strong> (millilitre), <strong>kuċċarina</strong> (teaspoon), <strong>nofs</strong> (half), <strong>ftit</strong> (a little).</li><li>Common recipe imperatives: <strong>itfa’</strong> (put in), <strong>ħawwad</strong> (stir), <strong>żid</strong> (add), <strong>farrak</strong> (crush), <strong>ifrex</strong> (spread), <strong>aħmi</strong> (bake).</li><li>Dressing agreement: <strong>liebes</strong> (m), <strong>liebsa</strong> (f), <strong>libsin / lebsin</strong> (plural); colours agree with the noun they modify, not mechanically with the wearer&#39;s gender.</li><li>Number structure: <strong>erbgħa</strong> standalone &quot;four&quot;, <strong>erba’ snin</strong> &quot;four years&quot;; <strong>tliet kotba</strong> three books, <strong>ħdax-il ktieb</strong> eleven books, <strong>għoxrin ktieb</strong> twenty books.</li><li>Learn the dual as whole words: <strong>jumejn</strong> two days, <strong>sagħtejn</strong> two hours, <strong>ġimagħtejn</strong> two weeks, <strong>xahrejn</strong> two months, <strong>sentejn</strong> two years, <strong>darbtejn</strong> twice.</li></ol>',214),a=[s];function i(g,d,l,b,h,u){return r(),n("div",null,a)}const c=t(o,[["render",i]]);export{f as __pageData,c as default};
